/** All translations for zizhitongjian ch.022 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起昭陽協洽，盡閼逢敦牂，凡十二年。", literal: "From Zhaoyang Xiehe through Efeng Dunjiang; twelve years in all.", idiomatic: "From Zhaoyang Xiehe through Efeng Dunjiang—twelve years in all." },
  { zh: "世宗孝武皇帝下之下 天漢三年（癸未，公元前九八年） 1 春，二月，王卿有罪自殺，以執金吾杜周為御史大夫。", literal: "Shizong Emperor Xiaowu, Lower Part Two. Tianhan year 3 (guiwei, 98 BCE). 1. In spring, the second month, Wang Qing, guilty of a crime, killed himself; Commandant of the Capital Guard Du Zhou was made Censor-in-Chief.", idiomatic: "Shizong Emperor Xiaowu, Lower Part Two. Tianhan year 3 (guiwei, 98 BCE). 1. In spring, the second month, Wang Qing, found guilty of a crime, killed himself; Commandant of the Capital Guard Du Zhou was made Censor-in-Chief." },
  { zh: "---- 2 初榷酒酤。", literal: "----2 For the first time wine was monopolized for franchised sale.", idiomatic: "----2 For the first time the state monopolized wine for franchised sale." },
  { zh: "---- 3 三月，上行幸泰山，脩封，祀明堂，因受計。", literal: "----3 In the third month, the emperor traveled in favor to Mount Tai, performed the feng, sacrificed at the Bright Hall, and thereupon received the annual accounts.", idiomatic: "----3 In the third month, the emperor traveled to Mount Tai, performed the feng, sacrificed at the Bright Hall, and thereupon received the annual accounts." },
  { zh: "還，祠常山，瘞玄玉。", literal: "On returning, he sacrificed at Mount Chang and buried dark jade.", idiomatic: "On his return he sacrificed at Mount Chang and buried dark jade." },
  { zh: "方士之候祠神人、入海求蓬萊者終無有驗，而公孫卿猶以大人跡為解。", literal: "The masters of the methods who awaited spirit-men at sacrifices and those who entered the sea seeking Penglai in the end had no verification, yet Gongsun Qing still explained it by the footprints of a great man.", idiomatic: "The masters of the methods who awaited spirit-men at sacrifices and those who entered the sea seeking Penglai never obtained proof, yet Gongsun Qing still explained it away with the footprints of a great man." },
  { zh: "天子益怠厭方士之怪迂語矣，然猶羈縻不絕，冀遇其真。", literal: "The Son of Heaven grew ever more slack and weary of the masters' strange and perverse talk, yet still kept them tethered without cutting them off, hoping to encounter a true one.", idiomatic: "The emperor grew ever more weary of the masters' strange and perverse talk, yet still kept them tethered without cutting them off, hoping to encounter a true one." },
  { zh: "自此之後，方士言神祠者彌眾，然其效可睹矣。", literal: "From this time onward, masters of the methods who spoke of spirit worship grew ever more numerous, yet their effects could be seen.", idiomatic: "From this time onward, masters who spoke of spirit worship grew ever more numerous, yet their effects were plain to see." },
  { zh: "---- 4 夏，四月，大旱。", literal: "----4 In summer, the fourth month, there was great drought.", idiomatic: "----4 In summer, the fourth month, there was great drought." },
  { zh: "赦天下。", literal: "An amnesty was proclaimed for all under Heaven.", idiomatic: "An amnesty was proclaimed for all under Heaven." },
  { zh: "---- 5 秋，匈奴入雁門。", literal: "----5 In autumn, the Xiongnu entered Yanmen.", idiomatic: "----5 In autumn, the Xiongnu entered Yanmen." },
  { zh: "太守坐畏愞棄市。", literal: "The governor, convicted of cowardice and slackness, was abandoned in the marketplace.", idiomatic: "The governor, convicted of cowardice and slackness, was executed in the marketplace." },
  { zh: "---- 天漢四年（甲申，公元前九七年） 1 春，正月，朝諸侯王於甘泉宮。", literal: "----Tianhan year 4 (jiashen, 97 BCE). 1. In spring, the first month, the feudal kings were received in audience at Ganquan Palace.", idiomatic: "----Tianhan year 4 (jiashen, 97 BCE). 1. In spring, the first month, the feudal kings were received in audience at Ganquan Palace." },
  { zh: "---- 2 發天下七科謫及勇敢士，遣貳師將軍李廣利將騎六萬、步兵七萬出朔方；", literal: "----2 Troops were raised from all under Heaven among the seven categories of banishment and brave men; Ershi General Li Guangli was sent leading sixty thousand cavalry and seventy thousand infantry out from Shuofang;", idiomatic: "----2 Troops were raised from across the realm among the seven categories of banishment and brave men; Ershi General Li Guangli was sent with sixty thousand cavalry and seventy thousand infantry out from Shuofang;" },
  { zh: "強弩都尉路博德將萬餘人與貳師會；", literal: "Strong Crossbow Commandant Lu Bode led more than ten thousand men to join Ershi;", idiomatic: "Strong Crossbow Commandant Lu Bode led more than ten thousand men to join Ershi;" },
  { zh: "游擊將軍韓說將步兵三萬人出五原；", literal: "Mobile Strike General Han Yue led thirty thousand infantry out from Wuyuan;", idiomatic: "Mobile Strike General Han Yue led thirty thousand infantry out from Wuyuan;" },
  { zh: "因杅將軍公孫敖將騎萬、步兵三萬人出雁門。", literal: "Yin'yu General Gongsun Ao led ten thousand cavalry and thirty thousand infantry out from Yanmen.", idiomatic: "Yin'yu General Gongsun Ao led ten thousand cavalry and thirty thousand infantry out from Yanmen." },
  { zh: "匈奴聞之，悉遠其累重於余吾水北；", literal: "The Xiongnu heard of it and all moved their baggage far to the north of the Yuwu River;", idiomatic: "The Xiongnu heard of it and moved all their baggage far north of the Yuwu River;" },
  { zh: "而單于以兵十萬待水南，與貳師接戰。", literal: "the chanyu with a hundred thousand troops waited south of the water and engaged Ershi in battle.", idiomatic: "the chanyu with a hundred thousand troops waited south of the river and engaged Ershi in battle." },
  { zh: "貳師解而引歸，與單于連鬥十餘日。", literal: "Ershi disengaged and withdrew, fighting the chanyu in succession for more than ten days.", idiomatic: "Ershi disengaged and withdrew, fighting the chanyu in succession for more than ten days." },
  { zh: "游擊無所得。", literal: "Mobile Strike gained nothing.", idiomatic: "Mobile Strike gained nothing." },
  { zh: "因杅與左賢王戰，不利，引歸。", literal: "Yin'yu fought the Left Worthy King, did not prevail, and withdrew.", idiomatic: "Yin'yu fought the Left Worthy King, did not prevail, and withdrew." },
  { zh: "時上遣敖深入匈奴迎李陵，敖軍無功還，因曰：「捕得生口，言李陵教單于為兵以備漢軍，故臣無所得。", literal: "At that time the emperor had sent Ao deep into the Xiongnu to welcome Li Ling; Ao's army returned without achievement and thereupon said: \"We captured a live captive who said Li Ling taught the chanyu to array troops against the Han army, and therefore your subject gained nothing.", idiomatic: "At that time the emperor had sent Ao deep into the Xiongnu to welcome Li Ling; Ao's army returned without success and reported, \"We captured a live captive who said Li Ling taught the chanyu to array troops against the Han army, and therefore your subject gained nothing." },
  { zh: "」上於是族陵家。", literal: "\" The emperor thereupon exterminated Ling's clan.", idiomatic: "\" The emperor thereupon exterminated Ling's clan." },
  { zh: "既而聞之，乃漢將降匈奴者李緒，非陵也。", literal: "Soon afterward it was heard that it was Li Xu, a Han general who had surrendered to the Xiongnu, and not Ling.", idiomatic: "Soon afterward it was learned that it was Li Xu, a Han general who had surrendered to the Xiongnu, and not Ling." },
  { zh: "陵使人刺殺緒。", literal: "Ling sent men to stab and kill Xu.", idiomatic: "Ling sent men to stab and kill Xu." },
  { zh: "大閼氏欲殺陵，單于匿之北方。", literal: "The Grand Consort wished to kill Ling; the chanyu hid him in the north.", idiomatic: "The Grand Consort wished to kill Ling; the chanyu hid him in the north." },
  { zh: "大閼氏死，乃還。", literal: "When the Grand Consort died, he then returned.", idiomatic: "When the Grand Consort died, he returned." },
  { zh: "單于以女妻陵，立為右校王，與衛律皆貴用事。", literal: "The chanyu gave his daughter in marriage to Ling and established him as Right Commandant King; he and Wei Lü were both honored and held power.", idiomatic: "The chanyu gave his daughter to Ling in marriage and made him Right Commandant King; he and Wei Lü were both honored and held power." },
  { zh: "衛律常在單于左右；", literal: "Wei Lü was constantly at the chanyu's side;", idiomatic: "Wei Lü was constantly at the chanyu's side;" },
  { zh: "陵居外，有大事乃入議。", literal: "Ling dwelt outside; only when there was a great affair did he enter to deliberate.", idiomatic: "Ling lived apart; only when a great affair arose did he enter to deliberate." },
  { zh: "---- 3 夏，四月，立皇子髆為昌邑王。", literal: "----3 In summer, the fourth month, the emperor's son Bo was established as King of Changyi.", idiomatic: "----3 In summer, the fourth month, the emperor's son Bo was established as King of Changyi." },
  { zh: "---- 太始元年（乙酉，公元前九六年） 1 春，正月，公孫敖坐妻為巫蠱要斬。", literal: "----Taishi year 1 (yiyou, 96 BCE). 1. In spring, the first month, Gongsun Ao, convicted because his wife practiced witchcraft, was beheaded at the waist.", idiomatic: "----Taishi year 1 (yiyou, 96 BCE). 1. In spring, the first month, Gongsun Ao, convicted because his wife practiced witchcraft, was beheaded at the waist." },
  { zh: "---- 2 徙郡國豪桀於茂陵。", literal: "----2 Powerful and prominent men of the commanderies and kingdoms were moved to Maoling.", idiomatic: "----2 Powerful and prominent men of the commanderies and kingdoms were moved to Maoling." },
  { zh: "---- 3 夏，六月，赦天下。", literal: "----3 In summer, the sixth month, an amnesty was proclaimed for all under Heaven.", idiomatic: "----3 In summer, the sixth month, an amnesty was proclaimed for all under Heaven." },
  { zh: "---- 4 是歲，匈奴且鞮侯單于死。", literal: "----4 That year, the Xiongnu chanyu Qiedi Hou died.", idiomatic: "----4 That year the Xiongnu chanyu Qiedi Hou died." },
  { zh: "有兩子，長為左賢王，次為左大將。", literal: "He had two sons: the elder was Left Worthy King, the younger Left Grand General.", idiomatic: "He had two sons: the elder was Left Worthy King, the younger Left Grand General." },
  { zh: "左賢王未至，貴人以為有病，更立左大將為單于。", literal: "The Left Worthy King had not arrived; the nobles thought him ill and instead established the Left Grand General as chanyu.", idiomatic: "The Left Worthy King had not arrived; the nobles thought him ill and instead made the Left Grand General chanyu." },
  { zh: "左賢王聞之，不敢進。", literal: "The Left Worthy King heard of it and did not dare advance.", idiomatic: "The Left Worthy King heard of it and did not dare advance." },
  { zh: "左大將使人召左賢王而讓位焉。", literal: "The Left Grand General sent men to summon the Left Worthy King and yield the throne to him.", idiomatic: "The Left Grand General sent men to summon the Left Worthy King and yield the throne to him." },
  { zh: "左賢王辭以病，左大將不聽，謂曰：「即不幸死，傳之於我。", literal: "The Left Worthy King declined on grounds of illness; the Left Grand General would not listen and said to him: \"If you should unhappily die, pass it to me.", idiomatic: "The Left Worthy King declined on grounds of illness; the Left Grand General would not listen and said, \"If you should die, pass the throne to me." },
  { zh: "」左賢王許之，遂立，為狐鹿姑單于。", literal: "\" The Left Worthy King assented; he was thereupon established as chanyu, titled Hulu Gu.", idiomatic: "\" The Left Worthy King assented; he was thereupon established as chanyu, titled Hulu Gu." },
  { zh: "以左大將為左賢王，數年，病死；", literal: "The Left Grand General was made Left Worthy King; after several years he died of illness;", idiomatic: "The Left Grand General was made Left Worthy King; after several years he died of illness;" },
  { zh: "其子先賢撣不得代，更以為日逐王。", literal: "his son Xianxian Shan could not succeed him and was instead made Riyu King.", idiomatic: "his son Xianxian Shan could not succeed him and was instead made Riyu King." },
  { zh: "單于自以其子為左賢王。", literal: "The chanyu himself made his own son Left Worthy King.", idiomatic: "The chanyu himself made his own son Left Worthy King." },
  { zh: "---- 太始二年（丙戌，公元前九五年） 1 春，正月，上行幸回中。", literal: "----Taishi year 2 (bingxu, 95 BCE). 1. In spring, the first month, the emperor traveled in favor to Huizhong.", idiomatic: "----Taishi year 2 (bingxu, 95 BCE). 1. In spring, the first month, the emperor traveled to Huizhong." },
  { zh: "---- 2 杜周卒，光祿大夫暴勝之為御史大夫。", literal: "----2 Du Zhou died; Palace Grandee Bao Shengzhi was made Censor-in-Chief.", idiomatic: "----2 Du Zhou died; Palace Grandee Bao Shengzhi was made Censor-in-Chief." },
  { zh: "---- 3 秋，旱。", literal: "----3 In autumn, there was drought.", idiomatic: "----3 In autumn, there was drought." },
  { zh: "---- 4 趙中大夫白公奏穿渠引涇水，首起谷口，尾入櫟陽，注渭中，袤二百里，溉田四千五百餘頃，因名曰白渠；", literal: "----4 Zhao Palace Grandee Bai Gong memorialized to cut a canal and draw the Jing River, beginning at Gukou and ending at Liyang, pouring into the Wei—two hundred li in length, irrigating more than forty-five hundred qing of fields; it was therefore named the Bai Canal;", idiomatic: "----4 Zhao Palace Grandee Bai Gong memorialized to cut a canal drawing the Jing River from Gukou to Liyang, pouring into the Wei—two hundred li long, irrigating more than forty-five hundred qing of fields; it was therefore named the Bai Canal;" },
  { zh: "民得其饒。", literal: "the people gained its abundance.", idiomatic: "the people gained its abundance." },
  { zh: "---- 太始三年（丁亥，公元前九四年） 1 春，正月，上行幸甘泉宮。", literal: "----Taishi year 3 (dinghai, 94 BCE). 1. In spring, the first month, the emperor traveled in favor to Ganquan Palace.", idiomatic: "----Taishi year 3 (dinghai, 94 BCE). 1. In spring, the first month, the emperor traveled to Ganquan Palace." },
  { zh: "二月，幸東海，獲赤雁。", literal: "In the second month, he favored Donghai and obtained a red wild goose.", idiomatic: "In the second month, he visited Donghai and obtained a red wild goose." },
  { zh: "幸琅邪，禮日成山，登之罘，浮大海而還。", literal: "He favored Langye, performed rites at Mount Richeng, ascended Mount Zhi, floated upon the great sea, and returned.", idiomatic: "He visited Langye, performed rites at Mount Richeng, ascended Mount Zhi, sailed upon the great sea, and returned." },
  { zh: "---- 2 是歲，皇子弗陵生。", literal: "----2 That year, the imperial son Fuling was born.", idiomatic: "----2 That year the imperial son Fuling was born." },
  { zh: "弗陵母曰河間趙倢伃，居鉤弋宮，任身十四月而生。", literal: "Fuling's mother was Lady Jieyi Zhao of Hejian, dwelling in Gouyi Palace; she carried the child fourteen months before giving birth.", idiomatic: "Fuling's mother was Lady Jieyi Zhao of Hejian, dwelling in Gouyi Palace; she carried the child fourteen months before giving birth." },
  { zh: "上曰：「聞昔堯十四月而生，今鉤弋亦然。", literal: "The emperor said: \"I have heard that in former times Yao was born after fourteen months; now Gouyi is likewise.", idiomatic: "The emperor said, \"I have heard that in former times Yao was born after fourteen months; now Gouyi is likewise." },
  { zh: "」乃命其所生門曰堯母門。", literal: "\" He thereupon ordered the gate where she gave birth called Gate of Yao's Mother.", idiomatic: "\" He thereupon named the gate where she gave birth Gate of Yao's Mother." },
  { zh: ":臣光曰：為人君者，動靜舉措不可不慎，發於中必形於外，天下無不知之。", literal: ": Your subject Guang says: As a ruler, movement and rest, every act and step cannot but be cautious; what arises within must take form without, and all under Heaven will know it.", idiomatic: ": Your subject Guang says: As a ruler, every movement and every act cannot but be cautious; what arises within must take form without, and all under Heaven will know it." },
  { zh: "當是時也，皇后、太子皆無恙，而命鉤弋之門曰堯母，非名也。", literal: "At that time the empress and crown prince were both unharmed, yet he named Gouyi's gate Yao's Mother—this was not a proper name.", idiomatic: "At that time the empress and crown prince were both unharmed, yet he named Gouyi's gate Yao's Mother—this was not a proper name." },
  { zh: "是以奸人逆探上意，知其奇愛少子，欲以為嗣，遂有危皇后、太子之心，卒成巫蠱之禍，悲夫！", literal: "For this reason wicked men probed the emperor's intent in reverse, knew he singularly loved the younger son and wished to make him heir, and thereupon harbored thoughts of endangering the empress and crown prince, until at last the witchcraft calamity was completed—how lamentable!", idiomatic: "For this reason wicked men probed the emperor's intent in reverse, knew he singularly loved the younger son and wished to make him heir, and harbored thoughts of endangering the empress and crown prince, until at last the witchcraft calamity was completed—how lamentable!" },
  { zh: "---- 3 趙人江充為水衡都尉。", literal: "----3 The Zhao man Jiang Chong was made Chief Steward for Water and Parks.", idiomatic: "----3 The Zhao man Jiang Chong was made Chief Steward for Water and Parks." },
  { zh: "初，充為趙敬肅王客，得罪於太子丹，亡逃；", literal: "At the outset, Chong had been a retainer of King Jingsu of Zhao, offended the heir Dan, and fled as a fugitive;", idiomatic: "At the outset Chong had been a retainer of King Jingsu of Zhao, offended the heir Dan, and fled;" },
  { zh: "詣闕告趙太子陰事，太子坐廢。", literal: "he came to the palace gates to report the Zhao heir's secret affairs, and the heir was deposed.", idiomatic: "he came to the palace gates to report the Zhao heir's secret affairs, and the heir was deposed." },
  { zh: "上召充入見。", literal: "The emperor summoned Chong to enter audience.", idiomatic: "The emperor summoned Chong to audience." },
  { zh: "充容貌魁岸，被服輕靡，上奇之；", literal: "Chong's appearance was lofty and imposing, his dress light and extravagant; the emperor marveled at him;", idiomatic: "Chong's appearance was lofty and imposing, his dress light and extravagant; the emperor marveled at him;" },
  { zh: "與語政事，大悅，由是有寵，拜為直指繡衣使者，使督察貴戚、近臣逾侈者。", literal: "in speaking with him of state affairs he was greatly pleased; thereby he gained favor and was appointed Straight-Pointing Embroidered-Robe Envoy, charged to oversee and inspect noble kin and close ministers who exceeded in extravagance.", idiomatic: "in speaking with him of state affairs he was greatly pleased; thereby he gained favor and was appointed Straight-Pointing Embroidered-Robe Envoy, charged to inspect noble kin and close ministers who exceeded in extravagance." },
  { zh: "充舉劾無所避，上以為忠直，所言皆中意。", literal: "Chong impeached without avoiding anyone; the emperor considered him loyal and upright, and everything he said hit the mark.", idiomatic: "Chong impeached without avoiding anyone; the emperor considered him loyal and upright, and everything he said hit the mark." },
  { zh: "嘗從上甘泉，逢太子家使乘車馬行馳道中，充以屬吏。", literal: "Once, following the emperor to Ganquan, he encountered the crown prince's household envoy driving a carriage and horses along the imperial speedway; Chong handed him over to the attending officials.", idiomatic: "Once, following the emperor to Ganquan, he encountered the crown prince's household envoy driving along the imperial speedway; Chong handed him over to the attending officials." },
  { zh: "太子聞之，使人謝充曰：「非愛車馬，誠不欲令上聞之，以教敕亡素者，唯江君寬之。", literal: "The crown prince heard of it and sent men to apologize to Chong, saying: \"It is not that I love the carriage and horses; I truly did not wish to let the emperor hear of it, lest he admonish my lack of discipline—only let Lord Jiang be lenient.", idiomatic: "The crown prince heard of it and sent men to apologize to Chong, saying, \"It is not that I love the carriage and horses; I truly did not wish the emperor to hear of it, lest he admonish my lack of discipline—only let Lord Jiang be lenient." },
  { zh: "」充不聽，遂白奏，上曰：「人臣當如是矣！", literal: "\" Chong would not listen and thereupon reported in memorial; the emperor said: \"A minister ought to be like this!", idiomatic: "\" Chong would not listen and reported in memorial; the emperor said, \"A minister ought to be like this!" },
  { zh: "」大見信用，威震京師。", literal: "\" He was greatly trusted and his authority shook the capital.", idiomatic: "\" He was greatly trusted and his authority shook the capital." },
  { zh: "---- 太始四年（戊子，公元前九三年） 1 春，三月，上行幸泰山。", literal: "----Taishi year 4 (wuzi, 93 BCE). 1. In spring, the third month, the emperor traveled in favor to Mount Tai.", idiomatic: "----Taishi year 4 (wuzi, 93 BCE). 1. In spring, the third month, the emperor traveled to Mount Tai." },
  { zh: "壬午，祀高祖於明堂以配上帝，因受計。", literal: "On renwu, he sacrificed to High Ancestor at the Bright Hall to accompany the High God, and thereupon received the accounts.", idiomatic: "On renwu he sacrificed to High Ancestor at the Bright Hall to accompany the High God, and thereupon received the accounts." },
  { zh: "癸未，祀孝景皇帝於明堂。", literal: "On guiwei, he sacrificed to Emperor Xiaojing at the Bright Hall.", idiomatic: "On guiwei he sacrificed to Emperor Xiaojing at the Bright Hall." },
  { zh: "甲申，修封。", literal: "On jiashen, he performed the feng.", idiomatic: "On jiashen he performed the feng." },
  { zh: "丙戌，禪石閭。", literal: "On bingxu, he performed the shan at Stone Lodge.", idiomatic: "On bingxu he performed the shan at Stone Lodge." },
  { zh: "夏，四月，幸不其。", literal: "In summer, the fourth month, he favored Buqi.", idiomatic: "In summer, the fourth month, he visited Buqi." },
  { zh: "五月，還，幸建章宮，赦天下。", literal: "In the fifth month, on returning, he favored Jianzhang Palace and proclaimed an amnesty for all under Heaven.", idiomatic: "In the fifth month, on his return, he visited Jianzhang Palace and proclaimed an amnesty for all under Heaven." },
  { zh: "---- 2 冬，十月，甲寅晦，日有食之。", literal: "----2 In winter, the tenth month, on the last day of the month jiayin, there was an eclipse of the sun.", idiomatic: "----2 In winter, the tenth month, on the last day of the month jiayin, there was a solar eclipse." },
  { zh: "---- 3 十二月，上行幸雍，祠五畤。", literal: "----3 In the twelfth month, the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "----3 In the twelfth month, the emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "西至安定、北地。", literal: "He went west to Anding and Beidi.", idiomatic: "He went west to Anding and Beidi." },
  { zh: "征和元年（己丑，公元前九二年） 1 春，正月，上還，幸建章宮。", literal: "Zhenghe year 1 (jichou, 92 BCE). 1. In spring, the first month, the emperor returned and favored Jianzhang Palace.", idiomatic: "Zhenghe year 1 (jichou, 92 BCE). 1. In spring, the first month, the emperor returned and visited Jianzhang Palace." },
  { zh: "---- 2 三月，趙敬肅王彭祖薨。", literal: "----2 In the third month, King Jingsu of Zhao Pengzu died.", idiomatic: "----2 In the third month, King Jingsu of Zhao Pengzu died." },
  { zh: "彭祖取江都易王所幸淖姬，生男，號淖子。", literal: "Pengzu took Nao Ji, whom King Yi of Jiangdu had favored, and she bore a son styled the Nao lad.", idiomatic: "Pengzu took Nao Ji, whom King Yi of Jiangdu had favored, and she bore a son styled the Nao lad." },
  { zh: "時淖姬兄為漢宦者，上召問：「淖子何如？", literal: "At that time Nao Ji's elder brother was a Han eunuch; the emperor summoned and asked: \"What of the Nao lad?", idiomatic: "At that time Nao Ji's elder brother was a Han eunuch; the emperor summoned him and asked, \"What of the Nao lad?" },
  { zh: "」對曰：「為人多欲。", literal: "\" He replied: \"He is a man of many desires.", idiomatic: "\" He replied, \"He is a man of many desires." },
  { zh: "」上曰：「多欲不宜君國子民。", literal: "\" The emperor said: \"Many desires do not suit ruling a state and governing the people.", idiomatic: "\" The emperor said, \"Many desires do not suit ruling a state and governing the people." },
  { zh: "」問武始侯昌，曰：「無咎無譽。", literal: "\" He asked Marquis of Wushi Chang, who said: \"Neither fault nor praise.", idiomatic: "\" He asked Marquis of Wushi Chang, who said, \"Neither fault nor praise." },
  { zh: "」上曰：「如是可矣。", literal: "\" The emperor said: \"Such as this will do.", idiomatic: "\" The emperor said, \"Such as this will do." },
  { zh: "」遣使者立昌為趙王。", literal: "\" He sent an envoy to establish Chang as King of Zhao.", idiomatic: "\" He sent an envoy to establish Chang as King of Zhao." },
  { zh: "---- 3 夏，大旱。", literal: "----3 In summer, there was great drought.", idiomatic: "----3 In summer, there was great drought." },
  { zh: "---- 4 上居建章宮，見一男子帶劍入中龍華門，疑其異人，命收之。", literal: "----4 The emperor dwelt at Jianzhang Palace and saw a man with a sword enter the Central Longhua Gate; suspecting him an extraordinary person, he ordered him seized.", idiomatic: "----4 The emperor was at Jianzhang Palace and saw a man with a sword enter the Central Longhua Gate; suspecting him an extraordinary person, he ordered him seized." },
  { zh: "男子捐劍走，逐之弗獲。", literal: "The man cast aside his sword and fled; they pursued him but did not capture him.", idiomatic: "The man cast aside his sword and fled; they pursued him but did not capture him." },
  { zh: "上怒，斬門候。", literal: "The emperor was angry and beheaded the gate warden.", idiomatic: "The emperor was angry and beheaded the gate warden." },
  { zh: "冬，十一月，發三輔騎士大搜上林，閉長安城門索；", literal: "In winter, the eleventh month, he raised knights of the Three Metropolises for a great search of Shanglin and closed the Chang'an city gates to hunt;", idiomatic: "In winter, the eleventh month, he raised knights of the Three Metropolises for a great search of Shanglin and closed the Chang'an city gates to hunt;" },
  { zh: "十一日乃解。", literal: "only after eleven days was the lock lifted.", idiomatic: "only after eleven days was the lock lifted." },
  { zh: "巫蠱始起。", literal: "The witchcraft affair first arose.", idiomatic: "The witchcraft affair first arose." },
  { zh: "---- 5 丞相公孫賀夫人君孺，衛皇后姊也，賀由是有寵。", literal: "----5 Chancellor Gongsun He's wife Junru was the Empress of Wei's elder sister; He thereby gained favor.", idiomatic: "----5 Chancellor Gongsun He's wife Junru was Empress Wei's elder sister; He thereby gained favor." },
  { zh: "賀子敬聲代父為太僕，驕奢不奉法，擅用北軍錢千九百萬；", literal: "He's son Jingsheng succeeded his father as Grand Master of the Household, was arrogant and extravagant and did not observe the law, and on his own authority used nineteen million of Northern Army funds;", idiomatic: "He's son Jingsheng succeeded his father as Grand Master of the Household, was arrogant and extravagant and did not observe the law, and on his own authority used nineteen million of Northern Army funds;" },
  { zh: "發覺，下獄。", literal: "when discovered, he was cast into prison.", idiomatic: "when discovered, he was cast into prison." },
  { zh: "是時詔捕陽陵大俠朱安世甚急，賀自請逐捕安世以贖敬聲罪，上許之。", literal: "At this time an edict urgently sought to capture the Yangling great hero Zhu Anshi; He volunteered to pursue and capture Anshi to redeem Jingsheng's crime; the emperor assented.", idiomatic: "At this time an edict urgently sought the Yangling great hero Zhu Anshi; He volunteered to pursue and capture Anshi to redeem Jingsheng's crime, and the emperor assented." },
  { zh: "後果得安世。", literal: "Later they indeed obtained Anshi.", idiomatic: "Later they indeed captured Anshi." },
  { zh: "安世笑曰：「丞相禍及宗矣！", literal: "Anshi laughed and said: \"The Chancellor's calamity will reach his clan!", idiomatic: "Anshi laughed and said, \"The Chancellor's calamity will reach his clan!" },
  { zh: "」遂從獄中上書，告「敬聲與陽石公主私通；", literal: "\" Thereupon from prison he memorialized, accusing \"Jingsheng had illicit relations with the Yangshi Princess;", idiomatic: "\" Thereupon from prison he memorialized, accusing Jingsheng of illicit relations with the Yangshi Princess;" },
  { zh: "上且上甘泉，使巫當馳道埋偶人，祝詛上，有惡言。", literal: "when the emperor would ascend to Ganquan, had witches bury doll figures on the imperial carriage road and curse the emperor with evil words.", idiomatic: "when the emperor would go to Ganquan, had witches bury doll figures on the imperial carriage road and curse the emperor with evil words." },
  { zh: "」 ---- 征和二年（庚寅，公元前九一年） 1 春，正月，下賀獄，案驗；", literal: "\" ---- Zhenghe year 2 (Gengyin, 91 BCE) 1 In spring, the first month, He was sent down to prison and investigated;", idiomatic: "\" ---- Zhenghe year 2 (Gengyin, 91 BCE) 1 In spring, the first month, He was imprisoned and investigated;" },
  { zh: "父子死獄中，家族。", literal: "Father and son died in prison; the clan was exterminated.", idiomatic: "Father and son died in prison, and the clan was exterminated." },
  { zh: "以涿郡太守劉屈氂為左丞相，封澎侯。", literal: "Liu Quji, Governor of Zhuo commandery, was made Left Chancellor and enfeoffed as Marquis of Peng.", idiomatic: "Liu Quji, Governor of Zhuo commandery, was made Left Chancellor and enfeoffed as Marquis of Peng." },
  { zh: "屈氂，中山靖王子也。", literal: "Quji was a son of King Jing of Zhongshan.", idiomatic: "Quji was a son of King Jing of Zhongshan." },
  { zh: "---- 2 夏，四月，大風，發屋折木。", literal: "---- 2 In summer, the fourth month, great wind tore houses open and broke trees.", idiomatic: "---- 2 In summer, the fourth month, a great wind tore houses open and broke trees." },
  { zh: "---- 3 閏月，諸邑公主、陽石公主及皇后弟子長平侯伉皆坐巫蠱誅。", literal: "---- 3 In the intercalary month, the Princess of Zhuyi, the Yangshi Princess, and the empress's nephew Marquis of Changping Kang were all executed for witchcraft.", idiomatic: "---- 3 In the intercalary month, the Princess of Zhuyi, the Yangshi Princess, and the empress's nephew Marquis of Changping Kang were all executed for witchcraft." },
  { zh: "---- 4 上行幸甘泉。", literal: "---- 4 The emperor traveled in favor to Ganquan.", idiomatic: "---- 4 The emperor traveled to Ganquan." },
  { zh: "---- 5 初，上年二十九乃生戾太子，甚愛之。", literal: "---- 5 At first, the emperor was twenty-nine when he bore the Aloof Crown Prince and greatly loved him.", idiomatic: "---- 5 At first the emperor was twenty-nine when the Aloof Crown Prince was born, and he greatly loved him." },
  { zh: "及長，性仁恕溫謹，上嫌其材能少，不類己；", literal: "When he grew up, his nature was benevolent, forgiving, warm, and cautious; the emperor disliked that his talent and ability were few and unlike himself;", idiomatic: "When he grew up, he was benevolent, forgiving, warm, and cautious; the emperor disliked his limited talent and ability, finding him unlike himself;" },
  { zh: "而所幸王夫人生子閎，李姬生子旦、胥，李夫人生子髆，皇后、太子寵浸衰，常有不自安之意。", literal: "while the Wang lady he favored bore Hong, Lady Li bore Dan and Xu, Lady Li bore Bo; the empress and crown prince's favor gradually declined, and they often had feelings of not being at ease.", idiomatic: "while the Wang lady he favored bore Hong, Lady Li bore Dan and Xu, and Lady Li bore Bo; favor toward the empress and crown prince gradually declined, and they often felt ill at ease." },
  { zh: "上覺之，謂大將軍青曰：「漢家庶事草創，加四夷侵陵中國，朕不變更制度，後世無法；", literal: "The emperor noticed and said to Grand General Qing: \"The Han house's many affairs are still in the founding stage, plus the four barbarians invade and harass China—if I do not change and renew institutions, later generations will have no models;", idiomatic: "The emperor noticed and said to Grand General Qing, \"The Han house's many affairs are still in the founding stage, and the four barbarians invade and harass China—if I do not change and renew institutions, later generations will have no models;" },
  { zh: "不出師征伐，天下不安；", literal: "if I do not send troops out to campaign and attack, all under Heaven will not be secure;", idiomatic: "if I do not send troops out to campaign, all under Heaven will not be secure;" },
  { zh: "為此者不得不勞民。", literal: "for this one cannot but burden the people.", idiomatic: "for this one cannot but burden the people." },
  { zh: "若後世又如朕所為，是襲亡秦之跡也。", literal: "If later generations again do as I do, that is following the traces of the perished Qin.", idiomatic: "If later generations again do as I do, that is following the path of the perished Qin." },
  { zh: "太子敦重好靜，必能安天下，不使朕憂。", literal: "The crown prince is staunch and grave and loves quiet—he will surely be able to secure all under Heaven and not make me worry.", idiomatic: "The crown prince is staunch and grave and loves quiet—he will surely secure all under Heaven and spare me worry." },
  { zh: "欲求守文之主，安有賢於太子者乎！", literal: "Wishing to seek a ruler who guards the written statutes, is there anyone more worthy than the crown prince!", idiomatic: "If one seeks a ruler who guards the written statutes, who is more worthy than the crown prince!" },
  { zh: "聞皇后與太子有不安之意，豈有之邪？", literal: "I have heard the empress and crown prince have feelings of unease—could there really be such a thing?", idiomatic: "I have heard the empress and crown prince feel uneasy—could that really be so?" },
  { zh: "可以意曉之。", literal: "You may convey my meaning to make them understand.", idiomatic: "You may convey my meaning to reassure them." },
  { zh: "」大將軍頓首謝。", literal: "\" The Grand General bowed his head in thanks.", idiomatic: "\" The Grand General bowed his head in thanks." },
  { zh: "皇后聞之，脫簪請罪。", literal: "The empress heard and removed her hairpin to beg forgiveness.", idiomatic: "The empress heard and removed her hairpin to beg forgiveness." },
  { zh: "太子每諫證伐四夷，上笑曰：「吾當其勞，以逸遺汝，不亦可乎！", literal: "The crown prince repeatedly remonstrated against campaigning against the four barbarians; the emperor laughed and said: \"I will bear the labor and leave ease to pass on to you—is that not acceptable!", idiomatic: "The crown prince repeatedly remonstrated against campaigning against the four barbarians; the emperor laughed and said, \"I will bear the labor and leave ease for you—is that not acceptable!" },
  { zh: "」 上每行幸，常以後事付太子，宮內付皇后。", literal: "\" Whenever the emperor traveled in favor, he often entrusted later affairs to the crown prince and matters within the palace to the empress.", idiomatic: "\" Whenever the emperor traveled, he often entrusted later affairs to the crown prince and palace matters to the empress." },
  { zh: "有所平決，還，白其最，上亦無異，有時不省也。", literal: "When there were decisions made, on return they reported the main points; the emperor also had no objection—sometimes he did not examine them.", idiomatic: "When decisions were made, on return they reported the main points; the emperor raised no objection—sometimes he did not even look into them." },
  { zh: "上用法嚴，多任深刻吏。", literal: "The emperor used law strictly and mostly employed severe, penetrating officials.", idiomatic: "The emperor applied the law strictly and mostly employed harsh, penetrating officials." },
  { zh: "太子寬厚，多所平反，雖得百姓心，而用法大臣皆不悅。", literal: "The crown prince was generous and thick and often overturned wrongful verdicts; though he gained the people's hearts, the law-using great ministers were all displeased.", idiomatic: "The crown prince was generous and often overturned wrongful verdicts; though he won the people's hearts, the ministers who applied the law were all displeased." },
  { zh: "皇后恐久獲罪，每戒太子，宜留取上意，不應擅有所縱捨。", literal: "The empress feared long obtaining guilt and repeatedly warned the crown prince that he should keep to the emperor's intent and should not on his own have releases and pardons.", idiomatic: "The empress feared she would eventually be blamed and repeatedly warned the crown prince to keep to the emperor's intent and not on his own grant releases and pardons." },
  { zh: "上聞之，是太子而非皇后。", literal: "The emperor heard and approved the crown prince but not the empress.", idiomatic: "The emperor heard and sided with the crown prince rather than the empress." },
  { zh: "群臣寬厚長者皆附太子，而深酷用法者皆毀之。", literal: "Among the ministers, generous, thick elders all attached to the crown prince, while those who deeply and cruelly used law all slandered him.", idiomatic: "Generous, senior ministers all attached to the crown prince, while those who applied the law harshly all slandered him." },
  { zh: "邪臣多黨與，故太子譽少而毀多。", literal: "Wicked ministers mostly had factions, so the crown prince had little praise and much slander.", idiomatic: "Wicked ministers mostly had factions, so praise of the crown prince was scant and slander abundant." },
  { zh: "衛青薨後，臣下無復外家為據，競欲構太子。", literal: "After Wei Qing died, the ministers below no longer had the maternal kin as reliance and competed to frame the crown prince.", idiomatic: "After Wei Qing died, the ministers no longer had the maternal kin as backing and competed to frame the crown prince." },
  { zh: "上與諸子疏，皇后希得見。", literal: "The emperor was distant from his sons; the empress rarely obtained audience.", idiomatic: "The emperor was distant from his sons, and the empress rarely saw him." },
  { zh: "太子嘗謁皇后，移日乃出。", literal: "The crown prince once called on the empress and only after a whole day came out.", idiomatic: "The crown prince once called on the empress and did not emerge until a whole day had passed." },
  { zh: "黃門蘇文告上曰：「太子與宮人戲。", literal: "The Yellow Gate Su Wen reported to the emperor: \"The crown prince was sporting with palace women.", idiomatic: "The Yellow Gate Su Wen reported to the emperor, \"The crown prince was sporting with palace women." },
  { zh: "」上益太子宮人滿二百人。", literal: "\" The emperor increased the crown prince's palace women to fill two hundred.", idiomatic: "\" The emperor increased the crown prince's palace women to two hundred." },
  { zh: "太子後知之，心銜文。", literal: "The crown prince later learned and bore resentment in heart toward Wen.", idiomatic: "The crown prince later learned of it and bore resentment toward Wen." },
  { zh: "文與小黃門常融、王弼等常微伺太子過，輒增加白之。", literal: "Wen with junior yellow gates Chang Rong, Wang Bi, and others constantly spied in secret for the crown prince's faults and whenever they found any added to their reports to the emperor.", idiomatic: "Wen with junior yellow gates Chang Rong, Wang Bi, and others constantly spied on the crown prince's faults and reported every one they found." },
  { zh: "皇后切齒，使太子白誅文等。", literal: "The empress gnashed her teeth and had the crown prince report to have Wen and the others executed.", idiomatic: "The empress gnashed her teeth and urged the crown prince to report and have Wen and the others executed." },
  { zh: "太子曰：「第勿為過，何畏文等！", literal: "The crown prince said: \"Just do not commit faults—why fear Wen and the rest!", idiomatic: "The crown prince said, \"Just do not commit faults—why fear Wen and the rest!" },
  { zh: "上聰明，不信邪佞，不足憂也」上嘗小不平，使常融召太子，融言「太子有喜色」，上嘿然。", literal: "The emperor is intelligent and does not believe the wicked and flattering—there is insufficient cause for worry.\" The emperor was once slightly unwell and had Chang Rong summon the crown prince; Rong said \"the crown prince had a pleased look\"; the emperor was silent.", idiomatic: "The emperor is intelligent and does not believe the wicked and flattering—there is no need to worry.\" The emperor was once slightly unwell and had Chang Rong summon the crown prince; Rong said the crown prince had a pleased look; the emperor was silent." },
  { zh: "及太子至，上察其貌，有涕泣處，而佯語笑，上怪之；", literal: "When the crown prince arrived, the emperor observed his appearance—there were places of weeping tears yet he pretended cheerful talk and laughter; the emperor found it strange;", idiomatic: "When the crown prince arrived, the emperor observed his appearance—there were traces of tears yet he pretended cheerful talk and laughter; the emperor found it strange;" },
  { zh: "更微問，知其情，乃誅融。", literal: "further questioning in secret, he learned his feelings, and thereupon executed Rong.", idiomatic: "questioning him further in secret, he learned the truth and executed Rong." },
  { zh: "皇后亦善自防閒，避嫌疑，雖久無寵，尚被禮遇。", literal: "The empress also was good at guarding herself against suspicion and avoiding doubtful points; though long without favor, she still received courtesy treatment.", idiomatic: "The empress also guarded herself carefully against suspicion; though long without favor, she still received courteous treatment." },
  { zh: "是時，方士及諸神巫多聚京師，率皆左道惑眾，變幻無所不為。", literal: "At this time, method masters and various spirit witches mostly gathered in the capital, generally all crooked ways deluding the masses, transforming and conjuring with nothing they would not do.", idiomatic: "At this time method masters and spirit witches mostly gathered in the capital, generally all crooked ways deluding the masses, conjuring anything they pleased." },
  { zh: "女巫往來宮中，教美人度厄，每屋輒埋木人祭祀之。", literal: "Witches went back and forth within the palace, teaching the beauties to pass through calamity; in every room they would bury wooden figures to sacrifice to them.", idiomatic: "Witches went back and forth within the palace, teaching the beauties rites to pass through calamity; in every room they buried wooden figures for sacrifice." },
  { zh: "因妒忌恚詈，更相告訐，以為祝詛上，無道。", literal: "Because of jealousy they cursed in anger and repeatedly accused one another, taking it as cursing the emperor—great impiety.", idiomatic: "Because of jealousy they cursed in anger and repeatedly accused one another of cursing the emperor—great impiety." },
  { zh: "上怒，所殺後宮延及大臣，死者數百人。", literal: "The emperor was angry; those killed in the rear palaces extended to great ministers—those who died numbered several hundred.", idiomatic: "The emperor was angry; executions in the rear palaces extended to great ministers, and several hundred died." },
  { zh: "上心既以為疑，嘗晝寢，夢木人數千持杖欲擊上，上驚寤，因是體不平，遂苦忽忽善忘。", literal: "The emperor's heart already harbored suspicion; he once slept by day and dreamed several thousand wooden figures holding staves wishing to strike the emperor; the emperor started awake in fright; because of this his body was unwell and he came to suffer restless forgetfulness.", idiomatic: "The emperor's heart already harbored suspicion; he once slept by day and dreamed several thousand wooden figures holding staves about to strike him; he started awake in fright; thereafter his health failed and he suffered restless forgetfulness." },
  { zh: "江充自以與太子及衛氏有隙，見上年老，恐晏駕後為太子所誅，因是為奸，言上疾祟在巫蠱。", literal: "Jiang Chong, considering himself to have a rift with the crown prince and the Wei clan, saw the emperor was old and feared that after the emperor's death he would be executed by the crown prince; he therefore acted wickedly, saying the emperor's illness and malign influence lay in witchcraft.", idiomatic: "Jiang Chong, knowing he had a rift with the crown prince and the Wei clan, saw the emperor was old and feared execution after the emperor's death; he therefore acted wickedly, saying the emperor's illness stemmed from witchcraft." },
  { zh: "於是上以充為使者，治巫蠱獄。", literal: "Thereupon the emperor made Chong an envoy to investigate the witchcraft case.", idiomatic: "Thereupon the emperor made Chong an envoy to investigate the witchcraft case." },
  { zh: "充將胡巫掘地求偶人，捕蠱及夜祠、視鬼，染污令有處，輒收捕驗治，燒鐵鉗灼，強服之。", literal: "Chong led Hu witches to dig earth seeking doll figures, captured sorcery and night sacrifices and spirit-viewing; where stained pollution could be placed they would arrest and verify and try, burning iron pincers to cauterize and forcing confession.", idiomatic: "Chong led Hu witches to dig earth seeking doll figures, captured sorcery, night sacrifices, and spirit-viewing; wherever tainted evidence could be planted they arrested and tried the accused, burning iron pincers to cauterize and forcing confession." },
  { zh: "民轉相誣以巫蠱，吏輒劾以為大逆無道；", literal: "The people turned and accused one another of witchcraft; officials would impeach them as great treason without norm;", idiomatic: "The people turned and accused one another of witchcraft; officials would impeach them as great treason;" },
  { zh: "自京師、三輔連及郡、國，坐而死者前後數萬人。", literal: "from the capital, the three metropolitan areas, extending to commanderies and kingdoms—those who sat convicted and died before and after numbered tens of thousands.", idiomatic: "from the capital and the three metropolitan areas to commanderies and kingdoms, those convicted and executed before and after numbered tens of thousands." },
  { zh: "是時，上春秋高，疑左右皆為蠱祝詛；", literal: "At this time the emperor's years were advanced; he suspected those left and right all practiced sorcery and cursed;", idiomatic: "At this time the emperor was advanced in years and suspected everyone around him of sorcery and cursing;" },
  { zh: "有與無，莫敢訟其冤者。", literal: "whether there was or was not, none dared argue their injustice.", idiomatic: "whether guilty or not, none dared plead their innocence." },
  { zh: "充既知上意，因胡巫檀何言：「宮中有蠱氣，不除之，上終不差。", literal: "Chong having known the emperor's intent, had the Hu witch Tan He say: \"Within the palace there is sorcery vapor; if not removed, the emperor will in the end not recover.", idiomatic: "Chong, knowing the emperor's intent, had the Hu witch Tan He say, \"Within the palace there is sorcery vapor; if not removed, the emperor will never recover." },
  { zh: "」上乃使充入宮，至省中，壞御座，掘地求蠱；", literal: "\" The emperor then had Chong enter the palace, reaching the inner apartments, broke imperial seats, and dug earth seeking sorcery;", idiomatic: "\" The emperor then had Chong enter the palace, reach the inner apartments, break imperial seats, and dig earth seeking sorcery;" },
  { zh: "又使按道侯韓說、御史章贛、黃門蘇文等助充。", literal: "and also had Marquis of Andao Han Shuo, censor Zhang Gan, Yellow Gate Su Wen, and others assist Chong.", idiomatic: "He also had Marquis of Andao Han Shuo, Censor Zhang Gan, Yellow Gate Su Wen, and others assist Chong." },
  { zh: "充先治後宮希幸夫人，以次及皇后、太子宮，掘地縱橫，太子、皇后無復施床處。", literal: "Chong first investigated the rear palace favored ladies, in order reaching the empress and crown prince's palace; digging earth crosswise and lengthwise, the crown prince and empress no longer had place to set beds.", idiomatic: "Chong first investigated favored ladies of the rear palace, then in turn the empress and crown prince's palaces; digging everywhere crosswise and lengthwise, the crown prince and empress no longer had room to set a bed." },
  { zh: "充云：「於太子宮得木人尤多，又有帛書，所言不道；", literal: "Chong said: \"In the crown prince's palace wooden figures obtained were especially many, and additionally there was silk writing; what was said was not according to the Way;", idiomatic: "Chong said, \"In the crown prince's palace especially many wooden figures were found, and additionally silk writing with impious words;" },
  { zh: "當奏聞。", literal: "it should be memorialized to inform.", idiomatic: "this should be memorialized to the throne." },
  { zh: "」太子懼，問少傅石德。", literal: "\" The crown prince was afraid and asked the Junior Tutor Shi De.", idiomatic: "\" The crown prince was afraid and asked Junior Tutor Shi De." },
  { zh: "德懼為師傅並誅，因謂太子曰：「前丞相父子、兩公主及衛氏皆坐此，今巫與使者掘地得征驗，不知巫置之邪，將實有也，無以自明。", literal: "De feared being executed together as tutor and therefore said to the crown prince: \"Previously the chancellor father and son, two princesses, and the Wei clan all sat convicted for this; now the witches and envoy dig earth and obtain verifying evidence—we do not know whether the witches placed them or they really exist; there is no means to clarify oneself.", idiomatic: "De feared being executed with his pupil and therefore said to the crown prince, \"Previously the chancellor father and son, two princesses, and the Wei clan were all convicted for this; now the witches and envoy dig earth and obtain evidence—we do not know whether the witches planted it or it really exists; there is no way to clear oneself." },
  { zh: "可矯以節收捕充等繫獄，窮治其奸詐。", literal: "You may falsely use the staff of office to arrest Chong and the rest and imprison them in prison, exhaustively trying their wicked deception.", idiomatic: "You may falsely use the staff of office to arrest Chong and the rest, imprison them, and exhaustively try their wicked deception." },
  { zh: "且上疾在甘泉，皇后及家吏請問皆不報；", literal: "Moreover the emperor's illness is at Ganquan; the empress and household officials' requests for news all go unanswered;", idiomatic: "Moreover the emperor is ill at Ganquan; the empress and household officials' requests for news all go unanswered;" },
  { zh: "上存亡未可知，而奸臣如此，太子將不念秦扶蘇事邪？", literal: "the emperor's survival or death is not yet known, while wicked ministers are like this—will the crown prince not recall the matter of Qin's Fusu?", idiomatic: "the emperor's survival is unknown, while wicked ministers act like this—will the crown prince not recall what happened to Qin's Fusu?" },
  { zh: "」太子曰：「吾人子，安得擅誅！", literal: "\" The crown prince said: \"I am a man's son—how can I on my own authority execute!", idiomatic: "\" The crown prince said, \"I am a son—how can I execute on my own authority!" },
  { zh: "不如歸謝，幸得無罪。", literal: "Better to return and apologize, perhaps obtaining no guilt.", idiomatic: "Better to go and apologize and hope to escape guilt." },
  { zh: "」太子將往之甘泉，而江充持太子甚急；", literal: "\" The crown prince was about to go to Ganquan, but Jiang Chong pressed the crown prince very urgently;", idiomatic: "\" The crown prince was about to go to Ganquan, but Jiang Chong pressed him very urgently;" },
  { zh: "太子計不知所出，遂從石德計。", literal: "the crown prince's plans knew nowhere to go out; he thereupon followed Shi De's plan.", idiomatic: "the crown prince could think of no way out and thereupon followed Shi De's plan." },
  { zh: "秋，七月，壬午，太子使客詐為使者，收捕充等。", literal: "In autumn, the seventh month, on renwu, the crown prince sent retainers falsely posing as envoys to arrest Chong and the rest.", idiomatic: "In autumn, the seventh month, on renwu, the crown prince sent retainers posing as envoys to arrest Chong and the rest." },
  { zh: "按道侯說疑使者有詐，不肯受詔，客格殺說。", literal: "Marquis of Andao Shuo suspected the envoys had deception and would not receive the edict; the retainers killed Shuo in struggle.", idiomatic: "Marquis of Andao Shuo suspected the envoys were fraudulent and refused the edict; the retainers killed him in the struggle." },
  { zh: "太子自臨斬充，罵曰：「趙虜！", literal: "The crown prince personally attended to behead Chong, cursing: \"Zhao barbarian!", idiomatic: "The crown prince personally beheaded Chong, cursing, \"Zhao barbarian!" },
  { zh: "前亂乃國王父子不足邪！", literal: "Previously you disturbed the Zhao king father and son—not enough!", idiomatic: "Was it not enough that you before ruined the Zhao king and his son!" },
  { zh: "乃復亂吾父子也！", literal: "Now again you disturb our father and son!", idiomatic: "Now you come again to ruin our father and son!" },
  { zh: "」又炙胡巫上林中。", literal: "\" He also roasted the Hu witch in Shanglin Park.", idiomatic: "\" He also roasted the Hu witch in Shanglin Park." },
  { zh: "太子使舍人無且持節夜入未央宮殿長秋門，因長御倚華具白皇后，發中廄車載射士，出武庫兵，發長樂宮衛卒。", literal: "The crown prince sent chamberlain Wunie holding the staff of office by night to enter Weiyang Palace's Eternal Autumn Gate; through chief attendant Yi Hua he fully informed the empress, issued central stable chariots carrying archers, brought out arsenal weapons, and mobilized Changle Palace guard troops.", idiomatic: "The crown prince sent Chamberlain Wunie with the staff of office by night through Weiyang Palace's Eternal Autumn Gate; through Chief Attendant Yi Hua he fully informed the empress, mobilized central stable chariots with archers, brought out arsenal weapons, and raised Changle Palace guard troops." },
  { zh: "長安擾亂，言太子反。", literal: "Chang'an was disturbed and chaotic; they said the crown prince had rebelled.", idiomatic: "Chang'an was thrown into turmoil; word spread that the crown prince had rebelled." },
  { zh: "蘇文迸走，得亡歸甘泉，說太子無狀。", literal: "Su Wen burst away running and obtained escape back to Ganquan, reporting the crown prince's misconduct.", idiomatic: "Su Wen fled and escaped back to Ganquan, reporting the crown prince's misconduct." },
  { zh: "上曰：「太子必懼，又忿充等，故有此變。", literal: "The emperor said: \"The crown prince must be afraid and also angry at Chong and the rest—therefore there is this change.", idiomatic: "The emperor said, \"The crown prince must be afraid and angry at Chong and the rest—hence this disturbance." },
  { zh: "」乃使使召太子。", literal: "\" He then sent an envoy to summon the crown prince.", idiomatic: "\" He then sent an envoy to summon the crown prince." },
  { zh: "使者不敢進，歸報云：「太子反已成，欲斬臣，臣逃歸。", literal: "The envoy did not dare advance and returned reporting: \"The crown prince's rebellion is already accomplished; he wished to behead your servant; your servant fled back.", idiomatic: "The envoy did not dare advance and returned reporting, \"The crown prince's rebellion is already accomplished; he wished to behead me, and I fled back." },
  { zh: "」上大怒。", literal: "\" The emperor was greatly angry.", idiomatic: "\" The emperor was greatly angry." },
  { zh: "丞相屈氂聞變，挺身逃，亡其印綬，使長史乘疾置以聞。", literal: "Chancellor Quji heard of the change, threw his body fleeing, lost his seal and cord, and had the chief clerk ride the express relay to report.", idiomatic: "Chancellor Quji heard of the disturbance, fled headlong, lost his seal and cord, and had the chief clerk ride the express relay to report." },
  { zh: "上問：「丞相何為？", literal: "The emperor asked: \"What is the Chancellor doing?", idiomatic: "The emperor asked, \"What is the Chancellor doing?" },
  { zh: "」對曰：「丞相秘之，未敢發兵。", literal: "\" Reply: \"The Chancellor is keeping it secret and does not dare send troops.", idiomatic: "\" The reply was, \"The Chancellor is keeping it secret and does not dare send troops." },
  { zh: "」上怒曰：「事籍籍如此，何謂秘也！", literal: "\" The emperor angrily said: \"The affair is so widespread and noisy—what is called secret!", idiomatic: "\" The emperor angrily said, \"The affair is so widespread—what do you mean by secret!" },
  { zh: "丞相無周公之風矣，周公不誅管、蔡乎！", literal: "The Chancellor lacks the Duke of Zhou's manner—did not the Duke of Zhou execute Guan and Cai!", idiomatic: "The Chancellor lacks the Duke of Zhou's spirit—did not the Duke of Zhou execute Guan and Cai!" },
  { zh: "」乃賜丞相璽書曰：「捕斬反者，自有賞罰。", literal: "\" He then bestowed on the Chancellor a sealed letter saying: \"Capturing and beheading rebels—there are rewards and punishments of their own.", idiomatic: "\" He then bestowed on the Chancellor a sealed letter saying, \"Capturing and beheading rebels carry their own rewards and punishments." },
  { zh: "以牛車為櫓，毋接短兵，多殺傷士眾！", literal: "Use oxcarts as shield-walls; do not engage with short weapons; do not greatly kill and wound officers and masses!", idiomatic: "Use oxcarts as shield-walls; do not engage at close quarters; do not greatly kill and wound troops!" },
  { zh: "堅閉城門，毋令反者得出！", literal: "Securely close the city gates; do not let rebels obtain exit!", idiomatic: "Securely close the city gates; do not let the rebels escape!" },
  { zh: "」太子宣言告令百官云：「帝在甘泉病困，疑有變；", literal: "\" The crown prince proclaimed and instructed the hundred officials, saying: \"The emperor is at Ganquan, ill and distressed, suspecting there is a change;", idiomatic: "\" The crown prince proclaimed to the hundred officials, \"The emperor is at Ganquan, gravely ill, and suspects a coup;" },
  { zh: "奸臣欲作亂。", literal: "wicked ministers wish to make rebellion.", idiomatic: "wicked ministers wish to rebel." },
  { zh: "」上於是從甘泉來，幸城西建章宮，詔發三輔近縣兵，部中二千石以下，丞相兼將之。", literal: "\" The emperor thereupon came from Ganquan, favored Jianzhang Palace west of the city, ordered mobilization of the three metropolitan areas' nearby counties' troops, those in departments and below two-thousand-dan, the Chancellor jointly commanding them.", idiomatic: "\" The emperor thereupon came from Ganquan to Jianzhang Palace west of the city, ordered troops mobilized from nearby counties of the three metropolitan areas, and had the Chancellor jointly command all officials in departments and below two-thousand-dan." },
  { zh: "太子亦遣使者矯制赦長安中都官囚徒，命少傅石德及賓客張光等分將；", literal: "The crown prince also sent envoys falsely using imperial orders to pardon Chang'an central capital officials' prisoners, ordered Junior Tutor Shi De and retainer Zhang Guang and others to divide command;", idiomatic: "The crown prince also sent envoys with forged orders to pardon Chang'an prisoners held by central capital officials, and ordered Junior Tutor Shi De and retainer Zhang Guang and others to divide command;" },
  { zh: "使長安囚如侯持節發長水及宣曲胡騎，皆以裝會。", literal: "had Chang'an prisoner Ru Hou holding the staff of office mobilize Changshui and Xuqu Hu cavalry—all to assemble fully equipped.", idiomatic: "and had Chang'an prisoner Ru Hou, holding the staff of office, mobilize Changshui and Xuqu Hu cavalry, all to assemble fully equipped." },
  { zh: "侍郎馬通使長安，因追捕如侯，告胡人曰：「節有詐，勿聽也！", literal: "Vice Minister Ma Tong was sent to Chang'an; pursuing Ru Hou along the way, he told the Hu: \"The staff is deceptive—do not obey it!", idiomatic: "Vice Minister Ma Tong was sent to Chang'an; pursuing Ru Hou along the way, he told the Hu, \"The staff is deceptive—do not obey it!" },
  { zh: "」遂斬如侯，引騎入長安；", literal: "\" Thereupon he beheaded Ru Hou and led horsemen into Chang'an;", idiomatic: "\" Thereupon he beheaded Ru Hou and led horsemen into Chang'an;" },
  { zh: "又發楫棹士以予大鴻臚商丘成。", literal: "He also sent boatmen and oarsmen to give to Grand Steward Shangqiu Cheng.", idiomatic: "He also sent boatmen and oarsmen to Grand Steward Shangqiu Cheng." },
  { zh: "初，漢節純赤，以太子持赤節，故更為黃旄加上以相別。", literal: "Initially Han staffs were pure red; because the crown prince held a red staff, they therefore changed to adding yellow pennants on top to distinguish them.", idiomatic: "Initially Han staffs were pure red; because the crown prince held a red staff, they therefore added yellow pennants on top to distinguish them." },
  { zh: "太子立車北軍南門外，召護北軍使者任安，與節，令發兵。", literal: "The crown prince stood by his chariot outside the south gate of the Northern Army barracks, summoned the envoy to protect the Northern Army Ren An, gave him the staff, and ordered him to raise troops.", idiomatic: "The crown prince stood by his chariot outside the south gate of the Northern Army barracks, summoned the envoy to protect the Northern Army Ren An, gave him the staff, and ordered him to raise troops." },
  { zh: "安拜受節；", literal: "An bowed and received the staff;", idiomatic: "An bowed and received the staff;" },
  { zh: "入，閉門不出。", literal: "entered, closed the gate, and did not come out.", idiomatic: "he entered, closed the gate, and did not come out." },
  { zh: "太子引兵去，驅四市人凡數萬眾，至長樂西闕下，逢丞相軍，合戰五日，死者數萬人，血流入溝中。", literal: "The crown prince led troops away, drove men from the four markets totaling tens of thousands, to below the western tower of Changle, met the Chancellor's army, and fought together five days; the dead were tens of thousands, and blood flowed into the ditches.", idiomatic: "The crown prince led troops away, drove men from the four markets totaling tens of thousands to below the western tower of Changle, met the Chancellor's army, and fought for five days; tens of thousands died, and blood flowed into the ditches." },
  { zh: "民間皆云太子反，以故眾不附太子，丞相附兵浸多。", literal: "Among the people all said the crown prince had rebelled; for this reason the masses did not attach to the crown prince, while the Chancellor's attached troops gradually increased.", idiomatic: "Among the people all said the crown prince had rebelled; for this reason the masses did not rally to the crown prince, while the Chancellor's attached troops gradually increased." },
  { zh: "庚寅，太子兵敗，南奔覆盎城門。", literal: "On gengyin, the crown prince's army was defeated and fled south to Fuchang Gate.", idiomatic: "On gengyin, the crown prince's army was defeated and fled south to Fuchang Gate." },
  { zh: "司直田仁部閉城門，以為太子父子之親，不欲急之，太子由是得出亡。", literal: "Director of Integrity Tian Ren's unit closed the city gate, thinking that as father and son the crown prince was kin and not wishing to press him hard; the crown prince thereby got out and fled.", idiomatic: "Director of Integrity Tian Ren's unit closed the city gate, thinking that as father and son the crown prince was kin and not wishing to press him hard; the crown prince thereby escaped." },
  { zh: "丞相欲斬仁，御史大夫暴勝之謂丞相曰：「司直，吏二千石，當先請，奈何擅斬之！", literal: "The Chancellor wished to execute Ren; Grand Counsellor Bao Shengzhi said to the Chancellor: \"Director of Integrity is an official of two thousand bushels—one should first request permission; how can you execute him on your own authority!", idiomatic: "The Chancellor wished to execute Ren; Grand Counsellor Bao Shengzhi said to the Chancellor, \"Director of Integrity is an official of two thousand bushels—one should first request permission; how can you execute him on your own authority!" },
  { zh: "」丞相釋仁。", literal: "\" The Chancellor released Ren.", idiomatic: "\" The Chancellor released Ren." },
  { zh: "上聞而大怒，下吏責問御史大夫曰：「司直縱反者，丞相斬之，法也；", literal: "The emperor heard it and was greatly angry; he sent officials down to rebuke and interrogate the Grand Counsellor, saying: \"Director of Integrity indulged rebels—the Chancellor executed him; that is the law;", idiomatic: "The emperor heard it and was greatly angry; he sent officials down to rebuke and interrogate the Grand Counsellor, saying, \"Director of Integrity indulged rebels—the Chancellor executed him; that is the law;" },
  { zh: "大夫何以擅止之？", literal: "why did you, Grand Counsellor, arbitrarily stop it?", idiomatic: "why did you, Grand Counsellor, arbitrarily stop it?" },
  { zh: "」勝之惶恐，自殺。", literal: "\" Shengzhi in fear and trembling killed himself.", idiomatic: "\" Shengzhi in fear and trembling killed himself." },
  { zh: "詔遣宗正劉長、執金吾劉敢奉策收皇后璽綬，后自殺。", literal: "An edict sent Director of the Imperial Clan Liu Chang and Commandant of the Metropolitan Guard Liu Gan bearing a decree to receive the empress's seal and ribbon; the empress killed herself.", idiomatic: "An edict sent Director of the Imperial Clan Liu Chang and Commandant of the Metropolitan Guard Liu Gan bearing a decree to receive the empress's seal and ribbon; the empress killed herself." },
  { zh: "上以為任安老吏，見兵事起，欲坐觀成敗，見勝者合從之，有兩心，與田仁皆要斬。", literal: "The emperor thought Ren An was an old official; when the military affair arose he wished to sit and observe success and failure, and when he saw the victor he would join with him—he had two hearts; with Tian Ren both were sentenced to decapitation at the waist.", idiomatic: "The emperor thought Ren An was an old official; when the military affair arose he wished to sit and observe success and failure, and when he saw the victor he would join with him—he had divided loyalties; with Tian Ren both were sentenced to decapitation at the waist." },
  { zh: "上以馬通獲如侯，長安男子景建從通獲石德，商丘成力戰獲張光，封通為重合侯，建為德侯，成為秺侯。", literal: "The emperor because Ma Tong captured Ru Hou, Chang'an man Jing Jian with Tong captured Shi De, and Shangqiu Cheng fought fiercely and captured Zhang Guang, enfeoffed Tong as Marquis of Chonghe, Jian as Marquis of De, and Cheng as Marquis of Zhe.", idiomatic: "Because Ma Tong captured Ru Hou, Chang'an man Jing Jian with Tong captured Shi De, and Shangqiu Cheng fought fiercely and captured Zhang Guang, the emperor enfeoffed Tong as Marquis of Chonghe, Jian as Marquis of De, and Cheng as Marquis of Zhe." },
  { zh: "諸太子賓客嘗出入宮門，皆坐誅；", literal: "All the crown prince's retainers who had gone in and out of the palace gates were punished with execution;", idiomatic: "All the crown prince's retainers who had gone in and out of the palace gates were punished with execution;" },
  { zh: "其隨太子發兵，以反法族，吏士劫略者皆徙敦煌郡。", literal: "those who followed the crown prince in raising troops, by the law of rebellion had their clans exterminated; officials and soldiers who plundered were all exiled to Dunhuang commandery.", idiomatic: "those who followed the crown prince in raising troops, by the law of rebellion had their clans exterminated; officials and soldiers who plundered were all exiled to Dunhuang commandery." },
  { zh: "以太子在外，始置屯兵長安諸城門。", literal: "Because the crown prince was outside, for the first time garrison troops were stationed at Chang'an's various city gates.", idiomatic: "Because the crown prince was outside, for the first time garrison troops were stationed at Chang'an's various city gates." },
  { zh: "上怒甚，群下憂懼，不知所出。", literal: "The emperor was greatly angry; the multitude below were worried and fearful, not knowing what to do.", idiomatic: "The emperor was greatly angry; the officials below were worried and fearful, not knowing what to do." },
  { zh: "壺關三老茂上書曰：「臣聞父者猶天，母者猶地，子猶萬物也，故天平，地安，物乃茂成；", literal: "Elder of Huguan Mao memorialized, saying: \"Your subject has heard that the father is like Heaven, the mother like Earth, the son like the ten thousand things—thus Heaven is balanced, Earth peaceful, and things then flourish and succeed;", idiomatic: "Elder of Huguan Mao memorialized, saying, \"Your subject has heard that the father is like Heaven, the mother like Earth, the son like the ten thousand things—thus Heaven is balanced, Earth peaceful, and things then flourish and succeed;" },
  { zh: "父慈，母愛，子乃孝順。", literal: "the father kind, the mother loving, the son then filial and obedient.", idiomatic: "the father kind, the mother loving, the son then filial and obedient." },
  { zh: "今皇太子為漢嗣，承萬世之業，體祖宗之重，親則皇帝之宗子也。", literal: "Now the crown prince is Han's heir, undertakes the enterprise of ten thousand generations, bears the weight of the ancestral temples—by kinship he is the emperor's eldest son.", idiomatic: "Now the crown prince is Han's heir, undertakes the enterprise of ten thousand generations, bears the weight of the ancestral temples—by kinship he is the emperor's eldest son." },
  { zh: "江充，布衣之人，閭閻之隸臣耳；", literal: "Jiang Chong is a man of common cloth, a lackey servant of lanes and alleys;", idiomatic: "Jiang Chong is a man of common cloth, a lackey servant of lanes and alleys;" },
  { zh: "陛下顯而用之，銜至尊之命以迫蹴皇太子，造飾奸詐，群邪錯繆，是以親戚之路鬲塞而不通。", literal: "Your Majesty prominently employed him, bearing the Most August command to press and trample the crown prince, fabricating wicked fraud; the wicked were confused and wrong—thereby the path of kin was blocked and not open.", idiomatic: "Your Majesty prominently employed him, bearing the Most August command to press and trample the crown prince, fabricating wicked fraud; the wicked were confused and wrong—thereby the path of kin was blocked and not open." },
  { zh: "太子進則不得見上，退則困於亂臣，獨冤結而無告，不忍忿忿之心，起而殺充，恐懼逋逃，子盜父兵，以救難自免耳。", literal: "The crown prince advancing could not see the emperor; retreating was trapped by disorderly ministers, alone wronged with no one to tell, unable to bear an angry heart—he rose and killed Chong, feared and fled; a son stole his father's troops to save calamity and exempt himself.", idiomatic: "The crown prince advancing could not see the emperor; retreating he was trapped by disorderly ministers, alone wronged with no one to tell, unable to bear an angry heart—he rose and killed Chong, feared and fled; a son stole his father's troops to save himself from calamity." },
  { zh: "臣竊以為無邪心。", literal: "Your subject privately thinks he had no rebellious heart.", idiomatic: "Your subject privately thinks he had no rebellious heart." },
  { zh: "《詩》曰：『營營青蠅，止於籓。", literal: "The Odes says: 'Buzzing green flies, stop at the fence.", idiomatic: "The Odes says, 'Buzzing green flies, stop at the fence." },
  { zh: "愷悌君子，無信讒言。", literal: "Harmonious, gentle gentleman—do not trust slanderous words.", idiomatic: "Harmonious, gentle gentleman—do not trust slanderous words." },
  { zh: "讒言罔極，交亂四國。", literal: "Slander reaches the limit, confuses and disorders the four states.", idiomatic: "Slander reaches the limit, confuses and disorders the four states." },
  { zh: "』往者江充讒殺趙太子，天下莫不聞。", literal: "' Formerly Jiang Chong by slander killed the Zhao crown prince—all under Heaven has heard it.", idiomatic: "' Formerly Jiang Chong by slander killed the Zhao crown prince—all under Heaven has heard it." },
  { zh: "陛下不省察，深過太子，發盛怒，舉大兵而求之，三公自將。", literal: "Your Majesty did not examine and investigate, deeply faulted the crown prince, sent forth great wrath, raised a great army to seek him, and the Three Excellencies led troops themselves.", idiomatic: "Your Majesty did not examine and investigate, deeply faulted the crown prince, sent forth great wrath, raised a great army to seek him, and the Three Excellencies led troops themselves." },
  { zh: "智者不敢言，辯士不敢說，臣竊痛之！", literal: "The wise dared not speak, debaters dared not argue—your subject privately grieves it!", idiomatic: "The wise dared not speak, debaters dared not argue—your subject privately grieves it!" },
  { zh: "唯陛下寬心慰意，少察所親，毋患太子之非，亟罷甲兵，無令太子久亡！", literal: "Only may Your Majesty broaden your heart and comfort your intent, slightly examine those close to you, do not worry over the crown prince's wrong, urgently halt armor and troops, and do not let the crown prince long remain a fugitive!", idiomatic: "Only may Your Majesty broaden your heart and comfort your intent, slightly examine those close to you, do not worry over the crown prince's wrong, urgently halt armor and troops, and do not let the crown prince long remain a fugitive!" },
  { zh: "臣不勝惓惓，出一旦之命，待罪建章宮下！", literal: "Your subject cannot bear earnest care, offers at once life's command, and awaits punishment below Jianzhang Palace!", idiomatic: "Your subject cannot bear earnest care, offers at once his life's command, and awaits punishment below Jianzhang Palace!" },
  { zh: "」書奏，天子感寤，然尚未顯言赦之也。", literal: "\" The memorial was presented; the Son of Heaven was moved and awakened, yet still did not openly say to pardon him.", idiomatic: "\" The memorial was presented; the Son of Heaven was moved and awakened, yet still did not openly say to pardon him." },
  { zh: "太子亡，東至湖，藏匿泉鳩里；", literal: "The crown prince fled, east to Hu, and hid at Quanjiu li;", idiomatic: "The crown prince fled east to Hu and hid at Quanjiu li;" },
  { zh: "主人家貧，常賣屨以給太子。", literal: "the host family was poor and often sold sandals to supply the crown prince.", idiomatic: "the host family was poor and often sold sandals to supply the crown prince." },
  { zh: "太子有故人在湖，聞其富贍，使人呼之而發覺。", literal: "The crown prince had an old acquaintance in Hu; hearing he was wealthy, he sent someone to summon him and was discovered.", idiomatic: "The crown prince had an old acquaintance in Hu; hearing he was wealthy, he sent someone to summon him and was discovered." },
  { zh: "八月，辛亥，吏圍捕太子。", literal: "In the eighth month, on xinhai, officials surrounded and captured the crown prince.", idiomatic: "In the eighth month, on xinhai, officials surrounded and captured the crown prince." },
  { zh: "太子自度不得脫，即入室距戶自經。", literal: "The crown prince estimated he could not escape, then entered the room, barred the door, and hanged himself.", idiomatic: "The crown prince estimated he could not escape, then entered the room, barred the door, and hanged himself." },
  { zh: "山陽男子張富昌為卒，足蹋開戶，新安令史李壽趨抱解太子。", literal: "Shanyang man Zhang Fuchang as a soldier kicked open the door with his foot; Xin'an order-clerk Li Shou rushed to embrace and undo the crown prince.", idiomatic: "Shanyang man Zhang Fuchang as a soldier kicked open the door with his foot; Xin'an order-clerk Li Shou rushed to embrace and undo the crown prince." },
  { zh: "主人公遂格鬥死，皇孫二人皆並遇害。", literal: "The host thereupon fought and died; the two imperial grandsons both together met calamity.", idiomatic: "The host thereupon fought and died; the two imperial grandsons both met calamity together." },
  { zh: "上既傷太子，乃封李壽為邘侯，張富昌為題侯。", literal: "The emperor, having grieved the crown prince, then enfeoffed Li Shou as Marquis of Yu and Zhang Fuchang as Marquis of Ti.", idiomatic: "The emperor, having grieved the crown prince, then enfeoffed Li Shou as Marquis of Yu and Zhang Fuchang as Marquis of Ti." },
  { zh: "初，上為太子立博望苑，使通賓客，從其所好，故賓客多以異端進者。", literal: "Initially the emperor for the crown prince established Bowang Park, allowed guests to come and go, and let him follow his preferences—therefore many retainers entered by heterodox ways.", idiomatic: "Initially the emperor for the crown prince established Bowang Park, allowed guests to come and go, and let him follow his preferences—therefore many retainers entered by heterodox ways." },
  { zh: ":臣光曰：古之明王教養太子，為之擇方正敦良之士，以為保傅、師友，使朝夕與之遊處。", literal: ": Your subject Guang says: Ancient enlightened kings in educating and nurturing the crown prince chose upright and honest worthy scholars for him as protectors, tutors, and friends, and made them morning and evening associate with him.", idiomatic: ": Your subject Guang says: Ancient enlightened kings in educating and nurturing the crown prince chose upright and honest worthy scholars for him as protectors, tutors, and friends, and made them morning and evening associate with him." },
  { zh: "左右前後無非正人，出入起居無非正道，然猶有淫放邪僻而陷於禍敗者焉，今乃使太子自通賓客，從其所好。", literal: "Left, right, before, behind—none were not upright men; going out and in, rising and resting—none were not upright paths—yet still there were those who indulged in dissipation and fell into disaster; now they let the crown prince himself receive guests and follow his likes.", idiomatic: "Left, right, before, behind—none were not upright men; going out and in, rising and resting—none were not upright paths—yet still there were those who indulged in dissipation and fell into disaster; now they let the crown prince himself receive guests and follow his likes." },
  { zh: "夫正直難親，諂諛易合，此固中人之常情，宜太子之不終也！", literal: "Uprightness is hard to be close to; flattery is easy to join—this is indeed the common feeling of mediocre men—no wonder the crown prince did not end well!", idiomatic: "Uprightness is hard to be close to; flattery is easy to join—this is indeed the common feeling of mediocre men—no wonder the crown prince did not end well!" },
  { zh: "---- 6 癸亥，地震。", literal: "---- 6 On guihai, an earthquake.", idiomatic: "---- 6 On guihai, there was an earthquake." },
  { zh: "---- 7 九月，商丘成為御史大夫。", literal: "---- 7 In the ninth month, Shangqiu Cheng was made Grand Counsellor.", idiomatic: "---- 7 In the ninth month, Shangqiu Cheng was appointed Grand Counsellor." },
  { zh: "---- 8 立趙敬肅王小子偃為平干王。", literal: "---- 8 The Zhao King Jing Su's young son Yan was established as King of Pinggan.", idiomatic: "---- 8 The Zhao King Jing Su's young son Yan was established as King of Pinggan." },
  { zh: "---- 9 匈奴入上谷，五原，殺掠吏民。", literal: "---- 9 The Xiongnu entered Shanggu and Wuyuan, killing and plundering officials and people.", idiomatic: "---- 9 The Xiongnu entered Shanggu and Wuyuan, killing and plundering officials and people." },
  { zh: "征和三年（辛卯，公元前九零年） 1 春，正月，上行幸雍，至安定、北地。", literal: "3rd year of Zhenghe (ximao, 90 BCE) 1 In spring, the first month, the emperor traveled in person to Yong, reaching Anding and Beidi.", idiomatic: "3rd year of Zhenghe (ximao, 90 BCE) 1 In spring, the first month, the emperor traveled in person to Yong, reaching Anding and Beidi." },
  { zh: "---- 2 匈奴入五原、酒泉，殺兩都尉。", literal: "---- 2 The Xiongnu entered Wuyuan and Jiuquan and killed two commandants.", idiomatic: "---- 2 The Xiongnu entered Wuyuan and Jiuquan and killed two commandants." },
  { zh: "三月，遣李廣利將七萬人出五原，商丘成將二萬人出西河，馬通將四萬騎出酒泉，擊匈奴。", literal: "In the third month, he sent Li Guangli leading seventy thousand men out from Wuyuan, Shangqiu Cheng leading twenty thousand out from Xihe, and Ma Tong leading forty thousand horsemen out from Jiuquan to strike the Xiongnu.", idiomatic: "In the third month, he sent Li Guangli leading seventy thousand men out from Wuyuan, Shangqiu Cheng leading twenty thousand out from Xihe, and Ma Tong leading forty thousand horsemen out from Jiuquan to strike the Xiongnu." },
  { zh: "---- 3 夏，五月，赦天下。", literal: "---- 3 In summer, the fifth month, amnesty for all under Heaven.", idiomatic: "---- 3 In summer, the fifth month, there was an amnesty for all under Heaven." },
  { zh: "---- 4 匈奴單于聞漢兵大出，悉徙其輜重北邸郅居水；", literal: "---- 4 The Xiongnu Chanyu heard Han troops had come out in force and wholly moved his baggage north to lodge at Zhi Ju River;", idiomatic: "---- 4 The Xiongnu Chanyu heard Han troops had come out in force and wholly moved his baggage north to lodge at Zhi Ju River;" },
  { zh: "左賢王驅其人民度余吾水六七百里，居兜銜山；", literal: "the Wise King of the Left drove his people across Yu Yuw River six or seven hundred li and dwelt at Douyan Mountain;", idiomatic: "the Wise King of the Left drove his people across Yu Yuw River six or seven hundred li and dwelt at Douyan Mountain;" },
  { zh: "單于自將精兵渡姑且水。", literal: "the Chanyu himself led picked troops across Guchu River.", idiomatic: "the Chanyu himself led picked troops across Guchu River." },
  { zh: "商丘成軍至，追邪徑，無所見，還。", literal: "Shangqiu Cheng's army arrived, pursued by deviant paths, saw nothing, and returned.", idiomatic: "Shangqiu Cheng's army arrived, pursued by deviant paths, saw nothing, and returned." },
  { zh: "匈奴使大將與李陵將三萬餘騎追漢軍，轉戰九日，至蒲奴水；", literal: "The Xiongnu sent a grand general with Li Ling leading more than thirty thousand horsemen to pursue the Han army; they fought in turns nine days, reaching Punu River;", idiomatic: "The Xiongnu sent a grand general with Li Ling leading more than thirty thousand horsemen to pursue the Han army; they fought in turns for nine days, reaching Punu River;" },
  { zh: "虜不利，還去。", literal: "the enemy was not advantaged and returned and left.", idiomatic: "the enemy was not advantaged and returned and left." },
  { zh: "馬通軍至天山，匈奴使大將偃渠將二萬餘騎要漢兵，見漢兵強，引去；", literal: "Ma Tong's army reached Tianshan; the Xiongnu sent Grand General Yan Qu leading more than twenty thousand horsemen to intercept Han troops; seeing Han troops were strong, he led away;", idiomatic: "Ma Tong's army reached Tianshan; the Xiongnu sent Grand General Yan Qu leading more than twenty thousand horsemen to intercept Han troops; seeing Han troops were strong, he led away;" },
  { zh: "通無所得失。", literal: "Tong had no gain or loss.", idiomatic: "Tong had no gain or loss." },
  { zh: "是時，漢恐車師遮馬通軍，遣開陵侯成娩將樓蘭、尉犁、危須等六國兵共圍車師，盡得其王民眾而還。", literal: "At this time Han feared Cheshi would block Ma Tong's army; it sent Marquis of Kailing Cheng Wan leading troops of Loulan, Weili, Weixu, and six states together to surround Cheshi, wholly obtained their king, people, and masses, and returned.", idiomatic: "At this time Han feared Cheshi would block Ma Tong's army; it sent Marquis of Kailing Cheng Wan leading troops of Loulan, Weili, Weixu, and six states together to surround Cheshi, wholly obtained their king, people, and masses, and returned." },
  { zh: "貳師將軍出塞，匈奴使右大都尉與衛律將五千騎要擊漢軍於夫羊句山峽，貳師擊破之，乘勝追北至范夫人城。", literal: "The Ershi general left the pass; the Xiongnu sent Right Grand Commandant with Wei Lü leading five thousand horsemen to intercept and strike the Han army at Fuyang Gou Mountain pass; the Ershi defeated them and, taking victory, pursued north to Fan Furen city.", idiomatic: "The Ershi general left the pass; the Xiongnu sent Right Grand Commandant with Wei Lü leading five thousand horsemen to intercept and strike the Han army at Fuyang Gou Mountain pass; the Ershi defeated them and, taking victory, pursued north to Fan Furen city." },
  { zh: "匈奴奔走，莫敢距敵。", literal: "The Xiongnu fled in panic; none dared resist the enemy.", idiomatic: "The Xiongnu fled in panic; none dared resist the enemy." },
  { zh: "初，貳師之出也，丞相劉屈氂為祖道，送至渭橋。", literal: "Initially, when the Ershi went out, Chancellor Liu Quji performed the road-leaving rite and sent him to Wei Bridge.", idiomatic: "Initially, when the Ershi went out, Chancellor Liu Quji performed the road-leaving rite and sent him to Wei Bridge." },
  { zh: "廣利曰：「願君侯早請昌邑王為太子；", literal: "Guangli said: \"I wish you, Lord Marquis, would early request the King of Changyi as crown prince;", idiomatic: "Guangli said, \"I wish you, Lord Marquis, would early request the King of Changyi as crown prince;" },
  { zh: "如立為帝，君侯長何憂乎！", literal: "if he is established as emperor, Lord Marquis long—what worry!", idiomatic: "if he is established as emperor, Lord Marquis—what long worry!" },
  { zh: "」屈氂許諾。", literal: "\" Quji promised.", idiomatic: "\" Quji promised." },
  { zh: "昌邑王者，貳師將軍女弟李夫人子也；", literal: "The King of Changyi was the Ershi general's younger sister Lady Li's son;", idiomatic: "The King of Changyi was the Ershi general's younger sister Lady Li's son;" },
  { zh: "貳師女為屈氂子妻，故共欲立焉。", literal: "the Ershi's daughter was Quji's son's wife—therefore together they wished to establish him.", idiomatic: "the Ershi's daughter was Quji's son's wife—therefore together they wished to establish him." },
  { zh: "會內者令郭穰告「丞相夫人祝詛上及與貳師共禱祠，欲令昌邑王為帝」，按驗，罪至大逆不道。", literal: "It happened the Inner Palace Clerk Guo Rang reported \"the Chancellor's wife cursed the emperor and together with the Ershi prayed at shrines, wishing to make the King of Changyi emperor\"—investigated, the offense reached great impiety and disloyalty.", idiomatic: "It happened the Inner Palace Clerk Guo Rang reported \"the Chancellor's wife cursed the emperor and together with the Ershi prayed at shrines, wishing to make the King of Changyi emperor\"—investigated, the offense reached great impiety and disloyalty." },
  { zh: "六月，詔載屈氂廚車以徇，要斬東市，妻子梟首華陽街；", literal: "In the sixth month, an edict carried Quji in the kitchen cart to display him, decapitated him at the waist in the eastern market, and his wife and children had their heads displayed on Huayang Street;", idiomatic: "In the sixth month, an edict carried Quji in the kitchen cart to display him, decapitated him at the waist in the eastern market, and his wife and children had their heads displayed on Huayang Street;" },
  { zh: "貳師妻子亦收。", literal: "the Ershi's wife and children were also arrested.", idiomatic: "the Ershi's wife and children were also arrested." },
  { zh: "貳師聞之，憂懼，其掾胡亞夫亦避罪從軍，說貳師曰：「夫人、室家皆在吏，若還，不稱意，適與獄會，郅居以北，可復得見乎！", literal: "The Ershi heard it and was worried and afraid; his aide Hu Yafu, also avoiding offense by following the army, advised the Ershi: \"Wife and household are all in officials' hands—if you return, not to one's liking, you will just meet with prison—north of Zhi Ju, can you again be seen!", idiomatic: "The Ershi heard it and was worried and afraid; his aide Hu Yafu, also avoiding offense by following the army, advised the Ershi, \"Wife and household are all in officials' hands—if you return, not to one's liking, you will just meet with prison—north of Zhi Ju, can you again be seen!" },
  { zh: "」貳師由是狐疑，深入要功，遂北至郅居水上。", literal: "\" The Ershi thereby hesitated, advanced deep to seek merit, and thereupon north to Zhi Ju waters.", idiomatic: "\" The Ershi thereby hesitated, advanced deep to seek merit, and thereupon north to Zhi Ju waters." },
  { zh: "虜已去，貳師遣護軍將二萬騎度郅居之水，逢左賢王、左大將將二萬騎，與漢軍合戰一日，漢軍殺左大將，虜死傷甚眾。", literal: "The enemy had already departed; the Ershi sent Protector of the Army with twenty thousand horsemen across Zhi Ju waters, met the Wise King of the Left and Left Grand General with twenty thousand horsemen, joined battle one day with the Han army—the Han army killed the Left Grand General, and the enemy dead and wounded were very many.", idiomatic: "The enemy had already departed; the Ershi sent Protector of the Army with twenty thousand horsemen across Zhi Ju waters, met the Wise King of the Left and Left Grand General with twenty thousand horsemen, joined battle one day with the Han army—the Han army killed the Left Grand General, and the enemy dead and wounded were very many." },
  { zh: "軍長史與決眭都尉輝渠侯謀曰：「將軍懷異心，欲危眾求功，恐必敗。", literal: "Army Chief Clerk together with Colonel of Resolve Wei Qu, Marquis Hui Qu, deliberated, saying: \"The general harbors a different heart, wishes to endanger the host and seek merit—fearing he will certainly be defeated.", idiomatic: "Army Chief Clerk together with Colonel of Resolve Wei Qu, Marquis Hui Qu, deliberated, saying, \"The general harbors a different heart, wishes to endanger the host and seek merit—fearing he will certainly be defeated." },
  { zh: "」謀共執貳師。", literal: "\" They plotted together to seize the Ershi.", idiomatic: "\" They plotted together to seize the Ershi." },
  { zh: "貳師聞之，斬長史，引兵還至燕然山。", literal: "The Ershi heard it, beheaded the Chief Clerk, and led troops back to Mount Yanran.", idiomatic: "The Ershi heard it, beheaded the Chief Clerk, and led troops back to Mount Yanran." },
  { zh: "單于知漢軍勞倦，自將五萬騎遮擊貳師，相殺傷甚眾；", literal: "The Chanyu knew the Han army was weary and exhausted, himself led fifty thousand horsemen to intercept and strike the Ershi, and mutual killing and wounding were very many;", idiomatic: "The Chanyu knew the Han army was weary and exhausted, himself led fifty thousand horsemen to intercept and strike the Ershi, and mutual killing and wounding were very many;" },
  { zh: "夜，塹漢軍前，深數尺，從後急擊之，軍大亂；", literal: "at night he trenched before the Han army several chi deep and from behind urgently struck them—the army was greatly disordered;", idiomatic: "at night he trenched before the Han army several chi deep and from behind urgently struck them—the army was greatly disordered;" },
  { zh: "貳師遂降。", literal: "the Ershi thereupon surrendered.", idiomatic: "the Ershi thereupon surrendered." },
  { zh: "單于素知其漢大將，以女妻之，尊寵在衛律上。", literal: "The Chanyu always knew he was a great Han general, gave him his daughter in marriage, and honor and favor were above Wei Lü.", idiomatic: "The Chanyu always knew he was a great Han general, gave him his daughter in marriage, and honor and favor were above Wei Lü." },
  { zh: "宗族遂滅。", literal: "The clan was thereupon extinguished.", idiomatic: "The clan was thereupon extinguished." },
  { zh: "---- 5 秋，蝗。", literal: "---- 5 In autumn, locusts.", idiomatic: "---- 5 In autumn, there were locusts." },
  { zh: "---- 6 九月，故城父令公孫勇與客胡倩等謀反，倩詐稱光祿大夫，言使督盜賊；", literal: "---- 6 In the ninth month, former Chengyang Magistrate Gongsun Yong with client Hu Qian and others plotted rebellion; Qian falsely claimed to be Palace Attendant, saying he was sent to supervise bandits;", idiomatic: "---- 6 In the ninth month, former Chengyang Magistrate Gongsun Yong with client Hu Qian and others plotted rebellion; Qian falsely claimed to be Palace Attendant, saying he was sent to supervise bandits;" },
  { zh: "淮陽太守田廣明覺知，發兵捕斬焉。", literal: "Huaiyang Administrator Tian Guangming detected it and sent troops to capture and behead them.", idiomatic: "Huaiyang Administrator Tian Guangming detected it and sent troops to capture and behead them." },
  { zh: "公孫勇衣繡衣、乘駟馬車至圉；", literal: "Gongsun Yong wore embroidered robes and rode a four-horse carriage to the stable park;", idiomatic: "Gongsun Yong wore embroidered robes and rode a four-horse carriage to the stable park;" },
  { zh: "圉守尉魏不害等誅之。", literal: "the stable park Commandant Wei Buhai and others executed him.", idiomatic: "the stable park Commandant Wei Buhai and others executed him." },
  { zh: "封不害等四人為侯。", literal: "Buhai and four others were enfeoffed as marquises.", idiomatic: "Buhai and four others were enfeoffed as marquises." },
  { zh: "---- 7 吏民以巫蠱相告言者，案驗多不實。", literal: "---- 7 Officials and people who reported one another for witchcraft—investigation mostly found them untrue.", idiomatic: "---- 7 Officials and people who reported one another for witchcraft—investigation mostly found them untrue." },
  { zh: "上頗知太子惶恐無它意，會高寢郎田千秋上急變，訟太子冤曰：「子弄父兵，罪當笞。", literal: "The emperor quite knew the crown prince was fearful with no other intent; it happened Bedchamber Attendant Tian Qianqiu urgently reported a change, pleading the crown prince's wrong, saying: \"A son played with his father's troops—the offense should be caning.", idiomatic: "The emperor quite knew the crown prince was fearful with no other intent; it happened Bedchamber Attendant Tian Qianqiu urgently reported a change, pleading the crown prince's wrong, saying, \"A son played with his father's troops—the offense should be caning." },
  { zh: "天子之子過誤殺人，當何罪哉！", literal: "The Son of Heaven's son in excess fault killed a man—what offense should it be!", idiomatic: "The Son of Heaven's son in excess fault killed a man—what offense should it be!" },
  { zh: "臣嘗夢一白頭翁教臣言。", literal: "Your subject once dreamed a white-haired old man taught your subject to speak.", idiomatic: "Your subject once dreamed a white-haired old man taught your subject to speak." },
  { zh: "」上乃大感寤，召見千秋，謂曰：「父子之間，人所難言也，公獨明其不然。", literal: "\" The emperor thereupon was greatly moved and awakened, summoned Qianqiu, and said: \"Between father and son, what men find hard to speak of—you alone clearly see it is not so.", idiomatic: "\" The emperor was deeply moved, summoned Qianqiu, and said, \"Between father and son, what men find hard to speak of—you alone clearly see it is not so." },
  { zh: "此高廟神靈使公教我，公當遂為吾輔佐。", literal: "This spirit of the High Temple made you teach me; you should proceed to be my aide and support.", idiomatic: "The spirit of the High Temple sent you to teach me; you shall be my chief minister." },
  { zh: "」立拜千秋為大鴻臚，而族滅江充家，焚蘇文於橫橋上，及泉鳩裡加兵刃於太子者，初為北地太守，後族。", literal: "\" He immediately appointed Qianqiu as Grand Herald; exterminated Jiang Chong's clan by degrees; burned Su Wen on Heng Bridge; and those who at Quanjiu Li added weapons against the heir apparent—first Northland governor, later clan exterminated.", idiomatic: "\" He immediately appointed Qianqiu Grand Herald; exterminated Jiang Chong's clan; burned Su Wen on Heng Bridge; and those who had armed themselves against the heir at Quanjiu Li—first the Northland governor, later their clans were exterminated." },
  { zh: "上憐太子無辜，乃作思子宮，為歸來望思之台於湖，天下聞而悲之。", literal: "The emperor pitied the heir was innocent; he thereupon built the Palace of Longing for the Son and made the Platform of Return to Look and Long at the lake; all under Heaven heard and grieved.", idiomatic: "Pitying the heir's innocence, the emperor built the Palace of Longing for the Son and the Platform of Return to Look and Long at the lake; all under Heaven heard and grieved." },
  { zh: "---- 征和四年（壬辰，公元前八九年） 1 春，正月，上行幸東萊，臨大海，欲浮海求神山。", literal: "---- Zhenghe year 4 (renchen, 89 BCE) 1 In spring, the first month, the emperor traveled in favor to Donglai, approached the great sea, and wished to float on the sea seeking divine mountains.", idiomatic: "---- Zhenghe year 4 (renchen, 89 BCE) 1 In spring, the first month, the emperor traveled to Donglai, approached the sea, and wished to sail in search of the divine mountains." },
  { zh: "群臣諫，上弗聽；", literal: "The ministers remonstrated; the emperor would not listen;", idiomatic: "The ministers remonstrated, but the emperor would not listen;" },
  { zh: "而大風晦冥，海水沸湧。", literal: "but great wind was dark and obscure, and the sea water boiled and surged.", idiomatic: "but great winds arose and the sky darkened, and the sea boiled and surged." },
  { zh: "上留十餘日，不得御樓船，乃還。", literal: "The emperor stayed more than ten days, could not mount tower ships, and thereupon returned.", idiomatic: "The emperor stayed more than ten days, could not board the tower ships, and returned." },
  { zh: "---- 2 二月，丁酉，雍縣無雲，如雷者三，隕石二，黑如黳。", literal: "----2 In the second month, on dingyou, in Yong county there were no clouds; like thunder three times; two meteorites fell, black as dark dye.", idiomatic: "----2 In the second month, on dingyou, Yong county had no clouds yet thundered three times; two meteorites fell, black as pitch." },
  { zh: "---- 3 三月，上耕於距定。", literal: "----3 In the third month, the emperor plowed at Juding.", idiomatic: "----3 In the third month the emperor performed the plowing ceremony at Juding." },
  { zh: "還，幸泰山，脩封。", literal: "Returning, he favored Mount Tai and performed the feng.", idiomatic: "On his return he traveled to Mount Tai and performed the feng." },
  { zh: "庚寅，祀於明堂。", literal: "On gengyin, he sacrificed at the Bright Hall.", idiomatic: "On gengyin he sacrificed at the Bright Hall." },
  { zh: "癸己，禪石閭，見群臣，上乃言曰：「朕即位以來，所為狂悖，使天下愁苦，不可追悔。", literal: "On guiji, he performed the chan at Stone Gate, saw the ministers, and the emperor thereupon spoke, saying: \"Since I took the throne, what I have done has been reckless and perverse, making all under Heaven sorrowful and bitter—this cannot be regretted away.", idiomatic: "On guiji he performed the chan at Stone Gate, saw the ministers, and said, \"Since I took the throne, my actions have been reckless and perverse, bringing sorrow to the realm—this cannot be undone." },
  { zh: "自今事有傷害百姓，糜費天下者，悉罷之。", literal: "From now on, whatever matters harm the people or waste the resources of all under Heaven—abolish them all.", idiomatic: "From now on, whatever harms the people or wastes the realm's resources shall be abolished." },
  { zh: "」田千秋曰：「方士言神仙者甚眾，而無顯功，臣請皆罷斥遣之。", literal: "\" Tian Qianqiu said: \"The fangshi who speak of immortals and spirits are very numerous, yet without manifest achievement; your servant requests that they all be dismissed and sent away.", idiomatic: "\" Tian Qianqiu said, \"Fangshi who speak of immortals are very numerous, yet accomplish nothing visible; your servant asks that they all be dismissed.\"" },
  { zh: "」上曰：「大鴻臚言是也。", literal: "\" The emperor said: \"The Grand Herald speaks correctly.", idiomatic: "\" The emperor said, \"The Grand Herald is right.\"" },
  { zh: "」於是悉罷諸方士候神人者。", literal: "\" Thereupon all the various fangshi awaiting spirits and divine men were dismissed.", idiomatic: "\" Thereupon all fangshi awaiting spirits and divine men were dismissed." },
  { zh: "是後上每對群臣自歎：「向時愚惑，為方士所欺。", literal: "After this, whenever the emperor faced the ministers he sighed to himself: \"Formerly I was foolish and deluded and was deceived by fangshi.", idiomatic: "After this, whenever he faced the ministers the emperor would sigh: \"I was once foolish and deluded and was deceived by fangshi." },
  { zh: "天下豈有仙人，盡妖妄耳！", literal: "How could there be immortals under Heaven?—all is demonic delusion!", idiomatic: "How could there be immortals under Heaven? It is all demonic nonsense!" },
  { zh: "節食服藥，差可少病而已。", literal: "Moderate eating and taking medicine can somewhat reduce illness—that is all.", idiomatic: "Eating moderately and taking medicine may somewhat reduce illness—that is all." },
  { zh: "」夏，六月，還，幸甘泉。", literal: "\" In summer, the sixth month, he returned and favored Sweet Springs.", idiomatic: "\" In summer, the sixth month, he returned and traveled to Sweet Springs." },
  { zh: "---- 4 丁巳，以大鴻臚田千秋為丞相，封富民侯。", literal: "----4 On dingsi, Tian Qianqiu, Grand Herald, was made Chancellor and enfeoffed as Marquis of Enriching the People.", idiomatic: "----4 On dingsi, Grand Herald Tian Qianqiu was made chancellor and enfeoffed as Marquis of Enriching the People." },
  { zh: "千秋無它材能，又無伐閱功勞，特以一言寤意，數月取宰相，封侯，世未嘗有也。", literal: "Qianqiu had no other talent or ability, and also no merit of campaigns or service; solely because one word awakened the emperor's mind, within months he obtained the chancellorship and was enfeoffed as marquis—the age had never had such a thing.", idiomatic: "Qianqiu had no other talent and no record of military merit; solely because one word awakened the emperor, within months he became chancellor and was enfeoffed as marquis—unprecedented in the age." },
  { zh: "然為人敦厚有智，居位自稱，逾於前後數公。", literal: "Yet as a man he was generous and wise; in office he restrained himself—surpassing several of his predecessors and successors.", idiomatic: "Yet he was generous and wise, and in office conducted himself with restraint, surpassing several chancellors before and after him." },
  { zh: "先是搜粟都尉桑弘羊與丞相、御史奏言：「輪台東有溉田五千頃以上，可遣屯田卒，置校尉三人分護，益種五穀；", literal: "Earlier the Search-for-Grain Colonel Sang Hongyang, together with the chancellor and the censor, memorialized, saying: \"East of Luntai there are irrigated fields of more than five thousand qing; garrison-farming soldiers may be sent, three colonels set to guard in divisions, and the planting of the five grains increased;", idiomatic: "Earlier Search-for-Grain Colonel Sang Hongyang, with the chancellor and censor, memorialized, \"East of Luntai are more than five thousand qing of irrigated fields; garrison-farming soldiers may be sent, three colonels appointed to guard in sections, and the five grains increased;\"" },
  { zh: "張掖、酒泉遣騎假司馬為斥候；", literal: "Zhangye and Jiuquan should send riding acting majors as scouts;", idiomatic: "Zhangye and Jiuquan should send mounted acting majors as scouts;" },
  { zh: "募民壯健敢徙者詣田所，益墾溉田，稍築列亭，連城而西，以威西國，輔烏孫。", literal: "recruit sturdy commoners willing to migrate to the farming sites, increase reclamation and irrigation, gradually build watchtowers in rows and link walls westward, to awe the western states and assist the Wusun.", idiomatic: "recruit sturdy commoners willing to migrate to the farming sites, increase reclamation and irrigation, gradually build watchtowers in rows linking walls westward, to awe the western states and assist the Wusun.\"" },
  { zh: "」上乃下詔，深陳既往之悔曰：「前有司奏欲益民賦三十，助邊用，是重困老弱孤獨也。", literal: "\" The emperor thereupon issued an edict deeply stating his past regret, saying: \"Formerly the offices memorialized wishing to increase the people's tax by thirty to aid border expenses—this heavily burdens the old, weak, orphaned, and alone.", idiomatic: "\" The emperor issued an edict deeply stating his past regret: \"Formerly the offices wished to increase the people's tax by thirty to aid border expenses—this would heavily burden the old, weak, orphaned, and alone." },
  { zh: "而今又請遣卒田輪台。", literal: "Now again they request sending soldiers to farm at Luntai.", idiomatic: "Now again they request sending soldiers to farm at Luntai." },
  { zh: "輪台西於車師千餘里，前開陵侯擊車師時，雖勝，降其王，以遼遠乏食，道死者尚數千人，況益西乎！", literal: "Luntai lies more than a thousand li west of Cheshi; when the Marquis of Kailing formerly attacked Cheshi, though victorious and having reduced their king, because of the distance and lack of food those who died on the road still numbered several thousand—how much more if one goes further west!", idiomatic: "Luntai lies more than a thousand li west of Cheshi; when the Marquis of Kailing attacked Cheshi, though victorious and having reduced their king, because of distance and lack of food several thousand died on the road—how much more if one goes further west!" },
  { zh: "曩者朕之不明，以軍候弘上書，言『匈奴縛馬前後足置城下，馳言「秦人，我匄若馬，」』又，漢使者久留不還，故興遣貳師將軍，欲以為使者威重也。", literal: "Formerly, because of my lack of clarity, when the army scout Hong memorialized, saying, 'The Xiongnu tied horses' front and rear feet and placed them below the city, then galloped saying, \"Qin men, I beg your horses,\"' and moreover Han envoys were long detained and not returned, I therefore raised and sent the General of the Ershi, wishing thereby to lend weight and prestige to the envoys.", idiomatic: "Formerly, in my lack of clarity, when army scout Hong memorialized that the Xiongnu had tied horses' front and rear feet beneath the city and galloped saying, \"Qin men, I beg your horses,\" and Han envoys had long been detained, I therefore sent the General of the Ershi to lend prestige to the envoys." },
  { zh: "古者卿、大夫與謀，參以蓍、龜，不吉不行。", literal: "In antiquity the nobles deliberated together and consulted yarrow and tortoise—if inauspicious, they did not proceed.", idiomatic: "In antiquity nobles deliberated and consulted yarrow and tortoise divination—if inauspicious, they did not act." },
  { zh: "乃者以縛馬書遍視丞相、御史、二千石、諸大夫、郎、為文學者，乃至郡、屬國都尉等，皆以『虜自縛其馬，不祥甚哉！", literal: "Recently, showing the tied-horse letter throughout to the chancellor, censor, two-thousand-bushel officials, the various grandees, gentlemen, literary officials, and even to commandery and dependent-state colonels and the like, all said, 'The barbarians tied their own horses—most inauspicious!", idiomatic: "Recently, when the tied-horse letter was shown to the chancellor, censor, two-thousand-bushel officials, grandees, gentlemen, literary officials, and even commandery and dependent-state colonels, all said, \"The barbarians tied their own horses—most inauspicious!\"" },
  { zh: "』或以為『欲以見強，夫不足者視人有餘。", literal: "' Or some thought, 'Wishing to show strength—those who are insufficient look at others as having surplus.'", idiomatic: "\" Or some thought, \"Wishing to show strength—those who lack look at others as having surplus.\"" },
  { zh: "』公車方士、太史、治星、望氣及太卜龜蓍皆以為『吉，匈奴必破，時不可再得也。", literal: "' The imperial-carriage fangshi, Grand Astrologer, star diviners, qi watchers, and the Grand Diviner with turtle and yarrow all said, 'Auspicious—the Xiongnu must be broken; the time cannot be gained again.'", idiomatic: "\" The imperial fangshi, Grand Astrologer, star diviners, qi watchers, and Grand Diviner with turtle and yarrow all said, \"Auspicious—the Xiongnu must be broken; the opportunity cannot come again.\"" },
  { zh: "』又曰：『北伐行將，於鬴山必克。", literal: "' They also said, 'The northern-campaign acting general at Fushan will surely conquer.'", idiomatic: "\" They also said, \"The northern-campaign acting general will surely conquer at Fushan.\"" },
  { zh: "卦，諸將貳師最吉。", literal: "By divination among the generals, the Ershi was most auspicious.", idiomatic: "By divination among the generals, the Ershi was most auspicious." },
  { zh: "』故朕親發貳師下鬴山，詔之必毋深入。", literal: "' Therefore I personally sent the Ershi down from Fushan and ordered him that he must not penetrate deeply.", idiomatic: "\" Therefore I personally sent the Ershi down from Fushan and ordered him not to penetrate deeply." },
  { zh: "今計謀、卦兆皆反繆。", literal: "Now plans and divinations all prove contrary and absurd.", idiomatic: "Now plans and divinations all prove contrary and absurd." },
  { zh: "重合侯得虜候者，乃言『縛馬者匈奴詛軍事也。", literal: "The Marquis of Chonghe obtained a barbarian scout and then said, 'Tying the horses was the Xiongnu cursing the military affair.'", idiomatic: "The Marquis of Chonghe obtained a Xiongnu scout who said, \"Tying the horses was a Xiongnu curse upon the army.\"" },
  { zh: "』匈奴常言『漢極大，然不耐飢渴，失一狼，走千羊。", literal: "' The Xiongnu often say, \"Han is extremely great, yet cannot bear hunger and thirst—lose one wolf and a thousand sheep run.\"'", idiomatic: "\" The Xiongnu often say, \"Han is extremely great, yet cannot bear hunger and thirst—lose one wolf and a thousand sheep run.\"" },
  { zh: "』乃者貳師敗，軍士死略離散，悲痛常在朕心。", literal: "' Recently the Ershi was defeated; soldiers died, were plundered, and scattered—the grief is always in my heart.", idiomatic: "\" Recently the Ershi was defeated; soldiers died, were plundered, and scattered—the grief is always in my heart." },
  { zh: "今又請遠田輪台，欲起亭隧，是擾勞天下，非所以優民也，朕不忍聞！", literal: "Now again they request farming Luntai from afar and wish to raise beacon towers and passes—this disturbs and burdens all under Heaven; it is not the way to favor the people. I cannot bear to hear it!", idiomatic: "Now again they request farming Luntai from afar and wish to raise beacon towers—this disturbs and burdens the realm; it is not how to favor the people. I cannot bear to hear it!" },
  { zh: "大鴻臚等又議欲募囚徒送匈奴使者，明封侯之賞以報忿，此五伯所弗為也。", literal: "The Grand Herald and others again discussed wishing to recruit convicts to pursue Xiongnu envoys, clarifying marquis rewards to answer rage—this is what the Five Hegemons would not do.", idiomatic: "The Grand Herald and others again discussed recruiting convicts to pursue Xiongnu envoys, with clear marquis rewards to answer rage—this the Five Hegemons would not do." },
  { zh: "且匈奴得漢降者常提掖搜索，問以所聞，豈得行其計乎！", literal: "Moreover, when the Xiongnu obtain Han surrenderers they constantly search and question them about what they have heard—how could their plan be carried out!", idiomatic: "Moreover, when the Xiongnu obtain Han surrenderers they constantly search and question them—how could such a plan be carried out!" },
  { zh: "當今務在禁苛暴，止擅賦，力本農，修馬復令，以補缺、毋乏武備而已。", literal: "The present task lies in forbidding harsh cruelty, stopping unauthorized levies, strengthening root agriculture, restoring the horse-relay statute, to fill gaps and not lack military preparation—that is all.", idiomatic: "The present task is to forbid harsh cruelty, stop unauthorized levies, strengthen agriculture, restore the horse-relay statute, to fill gaps and not lack military preparation—that is all." },
  { zh: "郡國二千石各上進畜馬方略補邊狀，與計對。", literal: "The two-thousand-bushel officials of commanderies and kingdoms shall each memorialize plans for raising horses and reports on border reinforcement, to be checked against the annual accounts.", idiomatic: "The two-thousand-bushel officials of commanderies and kingdoms shall each memorialize horse-raising plans and border-reinforcement reports, to be checked against the annual accounts." },
  { zh: "」 由是不復出軍，而封田千秋為富民侯，以明休息，思富養民也。", literal: "\" From this he no longer dispatched armies; he enfeoffed Tian Qianqiu as Marquis of Enriching the People to make clear rest and the intent to enrich and nourish the people.", idiomatic: "\" From this he no longer dispatched armies; he enfeoffed Tian Qianqiu as Marquis of Enriching the People to make clear his intent to rest, enrich, and nourish the people." },
  { zh: "又以趙過為搜粟都尉。", literal: "He also made Zhao Guo Search-for-Grain Colonel.", idiomatic: "He also made Zhao Guo Search-for-Grain Colonel." },
  { zh: "過能為代田，其耕耘田器皆有便巧，以教民，用力少而得穀多，民皆便之。", literal: "Guo was able to practice alternate-field farming; his plowing and field tools were all conveniently ingenious; he taught the people—using less effort yet obtaining more grain—and the people all found it convenient.", idiomatic: "Guo practiced alternate-field farming; his plows and field tools were all ingeniously convenient; he taught the people to use less labor and obtain more grain, and the people all welcomed it." },
  { zh: ":臣光曰：天下信未嘗無士也！", literal: ": Minister Guang said: Under Heaven truly has never lacked gentlemen!", idiomatic: ": Minister Guang said: Under Heaven truly has never lacked capable men!" },
  { zh: "武帝好四夷之功，而勇銳輕死之士充滿朝廷，闢土廣地，無不如意。", literal: "Emperor Wu loved achievements against the four Yi, and brave, sharp men who lightly faced death filled the court; opening land and expanding territory—nothing failed to go as wished.", idiomatic: "Emperor Wu loved achievements against the four barbarians, and brave, sharp men who lightly faced death filled the court; in opening land and expanding territory nothing failed to go as he wished." },
  { zh: "及後息民重農，而趙過之儔教民耕耘，民亦被其利。", literal: "When later he rested the people and emphasized agriculture, men like Zhao Guo taught the people plowing and cultivation, and the people also received their benefit.", idiomatic: "When later he rested the people and emphasized agriculture, men like Zhao Guo taught farming, and the people also benefited." },
  { zh: "此一君之身趣好殊別，而士輒應之，誠使武帝兼三王之量以興商、周之治，其無三代之臣乎！", literal: "Within one ruler's person his tastes differed so greatly, yet gentlemen at once responded to them—truly, if Emperor Wu had combined the measure of the Three Kings to revive the governance of Shang and Zhou, would he have lacked ministers of the Three Dynasties!", idiomatic: "Within one ruler's lifetime his tastes differed so greatly, yet gentlemen at once responded—truly, if Emperor Wu had possessed the measure of the Three Kings to revive Shang and Zhou governance, would he have lacked ministers of the Three Dynasties!" },
  { zh: "---- 5 秋，八月，辛酉晦，日有食之。", literal: "----5 In autumn, the eighth month, on the last day of the month xinyou, there was a solar eclipse.", idiomatic: "----5 In autumn, the eighth month, on the last day xinyou, there was a solar eclipse." },
  { zh: "---- 6 衛律害貳師之寵，會匈奴單于母閼氏病，律飭胡巫言：「先單于怒曰：『胡故時祠兵，常言得貳師以社，何故不用？", literal: "----6 Wei Lü resented the Ershi's favor; it happened the Xiongnu chanyu's mother the yanzhi was ill. Lü instructed a Hu shaman to say: \"The former chanyu was angry, saying, 'The Hu in former times sacrificed with weapons and always said, \"Obtain the Ershi for the altar sacrifice\"—why was he not used?'", idiomatic: "----6 Wei Lü resented the Ershi's favor; when the chanyu's mother the yanzhi fell ill, Lü instructed a Hu shaman to say, \"The former chanyu was angry, saying, 'The Hu formerly sacrificed with weapons and always said, Obtain the Ershi for the altar sacrifice—why was he not used?'\"" },
  { zh: "』」於是收貳師。", literal: "'\" Thereupon the Ershi was seized.", idiomatic: "\" Thereupon the Ershi was seized." },
  { zh: "貳師罵曰：「我死必滅匈奴！", literal: "The Ershi cursed, saying: \"When I die I will surely destroy the Xiongnu!", idiomatic: "The Ershi cursed, \"When I die I will destroy the Xiongnu!" },
  { zh: "」遂屠貳師以祠。", literal: "\" He was thereupon slaughtered as sacrifice.", idiomatic: "\" He was thereupon slaughtered as a sacrifice." },
  { zh: "---- 後元元年（癸巳，公元前八八年） 1 春，正月，上行幸甘泉，郊泰畤；", literal: "---- Houyuan year 1 (guisi, 88 BCE) 1 In spring, the first month, the emperor traveled in favor to Sweet Springs and suburban-sacrificed at the Great Altar;", idiomatic: "---- Houyuan year 1 (guisi, 88 BCE) 1 In spring, the first month, the emperor traveled to Sweet Springs and performed suburban sacrifice at the Great Altar;" },
  { zh: "遂幸安定。", literal: "he thereupon favored Anding.", idiomatic: "he then traveled to Anding." },
  { zh: "---- 2 昌邑哀王髆薨。", literal: "----2 The Lamented King of Changyi, Bo, died.", idiomatic: "----2 The Lamented King of Changyi, Bo, died." },
  { zh: "---- 3 二月，赦天下。", literal: "----3 In the second month, an amnesty for all under Heaven.", idiomatic: "----3 In the second month there was an amnesty for all under Heaven." },
  { zh: "---- 4 夏，六月，商丘成坐祝詛自殺。", literal: "----4 In summer, the sixth month, Shangqiu Cheng, convicted of curse-prayer, committed suicide.", idiomatic: "----4 In summer, the sixth month, Shangqiu Cheng, convicted of curse-prayer, committed suicide." },
  { zh: "---- 5 初，侍中僕射馬何羅與江充相善。", literal: "----5 Initially the attendant-in-ordinary and master of attendants Ma Heluo was on good terms with Jiang Chong.", idiomatic: "----5 Initially Attendant-in-Ordinary Ma Heluo was friendly with Jiang Chong." },
  { zh: "及衛太子起兵，何羅弟通以力戰封重合侯。", literal: "When the Heir of Wei raised troops, Heluo's younger brother Tong, through fierce fighting, was enfeoffed as Marquis of Chonghe.", idiomatic: "When the heir of Wei raised troops, Heluo's younger brother Tong was enfeoffed Marquis of Chonghe for fierce fighting." },
  { zh: "後上夷滅充宗族、黨與，何羅兄弟懼及，遂謀為逆。", literal: "Later the emperor exterminated Chong's clan and partisans; the Heluo brothers feared they would be reached and thereupon plotted rebellion.", idiomatic: "Later the emperor exterminated Chong's clan and allies; the Heluo brothers feared they would be implicated and plotted rebellion." },
  { zh: "侍中駙馬都尉金日磾視其志意有非常，心疑之，陰獨察其動靜，與俱上下。", literal: "The attendant and Commandant of the Imperial Son-in-Law Jin Midi saw his intent and bearing were extremely unusual and suspected him in his heart; secretly he alone observed his movements and accompanied him up and down.", idiomatic: "Attendant and Commandant of the Imperial Son-in-Law Jin Midi saw his intent was highly unusual and suspected him; secretly he observed his movements and accompanied him everywhere." },
  { zh: "何羅亦覺日磾意，以故久不得發。", literal: "Heluo also perceived Midi's intent; for this reason he long could not launch the plot.", idiomatic: "Heluo also sensed Midi's intent; for this reason he long could not act." },
  { zh: "是時上行幸林光宮，日磾小疾臥廬，何羅與通及小弟安成矯制夜出，共殺使者，發兵。", literal: "At this time the emperor was traveling in favor to Linqguang Palace; Midi had a minor illness and lay in his lodge. Heluo, together with Tong and his youngest brother Ancheng, forged an edict and went out by night, together killed the messenger, and raised troops.", idiomatic: "At this time the emperor was at Linqguang Palace; Midi lay ill in his lodge. Heluo, with Tong and his youngest brother Ancheng, forged an edict and went out by night, killed the messenger, and raised troops." },
  { zh: "明旦，上未起，何羅無何從外入。", literal: "At dawn the next day, before the emperor had risen, Heluo somehow entered from outside.", idiomatic: "At dawn the next day, before the emperor had risen, Heluo somehow entered from outside." },
  { zh: "日磾奏廁，心動，立入，坐內戶下。", literal: "Midi was at the privy; his heart stirred; he immediately entered and sat below the inner door.", idiomatic: "Midi was at the privy; his heart stirred; he immediately entered and sat below the inner door." },
  { zh: "須臾，何羅袖白刃從東廂上，見日磾，色變；", literal: "Shortly Heluo, with a white blade in his sleeve, ascended from the east wing; seeing Midi, his complexion changed;", idiomatic: "Shortly Heluo, with a bare blade in his sleeve, came up from the east wing; seeing Midi, his complexion changed;" },
  { zh: "走趨臥內，欲入，行觸寶瑟，僵。", literal: "he ran toward the sleeping quarters wishing to enter; walking, he struck the precious se and stiffened.", idiomatic: "he ran toward the sleeping quarters wishing to enter; walking, he struck the precious se and stiffened." },
  { zh: "日磾得抱何羅，因傳曰：「馬何羅反！", literal: "Midi was able to embrace Heluo and, passing word, said: \"Ma Heluo rebels!", idiomatic: "Midi seized Heluo and cried out, \"Ma Heluo rebels!" },
  { zh: "」上驚起。", literal: "\" The emperor started up in alarm.", idiomatic: "\" The emperor started up in alarm." },
  { zh: "左右拔刃欲格之，上恐並中日磾，止勿格。", literal: "Those left and right drew blades wishing to strike; the emperor feared they would hit Midi together and stopped them—do not strike.", idiomatic: "Those at his side drew blades to strike, but the emperor feared they would hit Midi as well and stopped them." },
  { zh: "日磾投何羅殿下，得禽縛之。", literal: "Midi threw Heluo below the hall and was able to seize and bind him.", idiomatic: "Midi threw Heluo below the hall and seized and bound him." },
  { zh: "窮治，皆伏辜。", literal: "Investigated to the end, all submitted to punishment.", idiomatic: "Investigated to the end, all submitted to punishment." },
  { zh: "---- 6 秋，七月，地震。", literal: "----6 In autumn, the seventh month, there was an earthquake.", idiomatic: "----6 In autumn, the seventh month, there was an earthquake." },
  { zh: "---- 7 燕王旦自以次第當為太子，上書求入宿衛。", literal: "----7 The King of Yan, Dan, thought that by order of succession he ought to be heir apparent and memorialized requesting to enter palace guard service.", idiomatic: "----7 The King of Yan, Dan, thought that by order of succession he ought to be heir apparent and memorialized requesting to enter palace guard service." },
  { zh: "上怒，斬其使於北闕；", literal: "The emperor was angry and beheaded his envoy at the northern gate;", idiomatic: "The emperor was angry and beheaded his envoy at the northern gate;" },
  { zh: "又坐藏匿亡命，削良鄉、安次、文安三縣。", literal: "he was also convicted of harboring fugitives and had the three counties Liangxiang, Anci, and Wen'an cut away.", idiomatic: "he was also convicted of harboring fugitives and had the three counties Liangxiang, Anci, and Wen'an stripped away." },
  { zh: "上由是惡旦。", literal: "The emperor thereby came to hate Dan.", idiomatic: "The emperor thereby came to hate Dan." },
  { zh: "旦辯慧博學，其弟廣陵王胥，有勇力，而皆動作無法度，多過失，故上皆不立。", literal: "Dan was eloquent, clever, and broadly learned; his younger brother the King of Guangling, Xu, had martial strength—yet both acted without law or measure and had many faults; therefore the emperor established neither.", idiomatic: "Dan was eloquent, clever, and broadly learned; his younger brother the King of Guangling, Xu, had martial strength—yet both acted lawlessly and had many faults; therefore the emperor established neither." },
  { zh: "時鉤弋夫人之子弗陵，年數歲，形體壯大，多知，上奇愛之，心欲立焉；", literal: "At this time Lady Gouyi's son Fuling was several years old, his body strong and large, knowing much; the emperor marveled and loved him and in his heart wished to establish him;", idiomatic: "At this time Lady Gouyi's son Fuling was only a few years old, yet sturdy and large and knowing much; the emperor marveled and loved him and wished to establish him;" },
  { zh: "以其年稚，母少，猶與久之。", literal: "because of his young age and his mother's youth, he still delayed long.", idiomatic: "but because the boy was young and his mother young, he still delayed." },
  { zh: "欲以大臣輔之，察群臣，唯奉車都尉、光祿大夫霍光，忠厚可任大事，上乃使黃門畫周公負成王朝諸侯以賜光。", literal: "Wishing to have great ministers assist him, he surveyed the ministers; only the Director of the Carriages and Palace Counsellor Huo Guang was loyal and generous and could be entrusted with great affairs. The emperor thereupon had the Yellow Gate paint the Duke of Zhou carrying the young king to face the feudal lords and gave it to Guang.", idiomatic: "Wishing to have great ministers assist him, he surveyed the ministers; only Director of the Carriages and Palace Counsellor Huo Guang was loyal and could be entrusted with great affairs. The emperor had the Yellow Gate paint the Duke of Zhou carrying the young king before the feudal lords and gave it to Guang." },
  { zh: "後數日，帝譴責鉤弋夫人。", literal: "Several days later the emperor reproached Lady Gouyi.", idiomatic: "Several days later the emperor reproached Lady Gouyi." },
  { zh: "夫人脫簪珥，叩頭。", literal: "The lady removed her hairpins and ear ornaments and kowtowed.", idiomatic: "The lady removed her hairpins and ear ornaments and kowtowed." },
  { zh: "帝曰：「引持去，送掖庭獄！", literal: "The emperor said: \"Take her away and send her to the Palace Rearward prison!", idiomatic: "The emperor said, \"Take her away and send her to the Palace Rearward prison!" },
  { zh: "」夫人還顧，帝曰：「趣行，汝不得活！", literal: "\" The lady turned her head to look back; the emperor said: \"Hurry—go; you cannot live!", idiomatic: "\" The lady looked back; the emperor said, \"Go quickly—you cannot live!" },
  { zh: "」卒賜死。", literal: "\" In the end she was granted death.", idiomatic: "\" In the end she was put to death." },
  { zh: "頃之，帝閒居，問左右曰：「外人言雲何？", literal: "Shortly after, the emperor was at leisure and asked those at his side: \"What do outsiders say?", idiomatic: "Shortly after, at leisure the emperor asked his attendants, \"What are outsiders saying?" },
  { zh: "」左右對曰：「人言『且立其子，何去其母乎？", literal: "\" Those left and right replied: \"People say, 'You are about to establish her son—why remove his mother?'", idiomatic: "\" They replied, \"People say, 'You are about to establish her son—why remove his mother?'\"" },
  { zh: "』」帝曰：「然，是非兒曹愚人之所知也。", literal: "'\" The emperor said: \"So—but this is not what children and fools can understand.", idiomatic: "\" The emperor said, \"So—but this is not what children and fools understand." },
  { zh: "往古國家所以亂，由主少、母壯也。", literal: "In former ages the reason states fell into disorder was that the ruler was young and the mother strong.", idiomatic: "In former ages states fell into disorder because the ruler was young and the mother strong." },
  { zh: "女主獨居驕蹇，淫亂自恣，莫能禁也。", literal: "The female ruler dwelling alone grows arrogant and obstinate, licentious and chaotic, indulging herself—none can forbid it.", idiomatic: "The empress dowager dwelling alone grows arrogant, licentious and self-indulgent—none can forbid it." },
  { zh: "汝不聞呂后邪！", literal: "Have you not heard of Empress Lü!", idiomatic: "Have you not heard of Empress Lü!" },
  { zh: "故不得不先去之也。", literal: "Therefore I could not but remove her first.", idiomatic: "Therefore I could not but remove her first." },
  { zh: "」 ---- 後元二年（甲午，公元前八七年） 1 春，正月，上朝諸侯王於甘泉宮。", literal: "\" ---- Houyuan year 2 (jiawu, 87 BCE) 1 In spring, the first month, the emperor held court with the feudal kings and princes at Sweet Springs Palace.", idiomatic: "\" ---- Houyuan year 2 (jiawu, 87 BCE) 1 In spring, the first month, the emperor held court with the feudal kings and princes at Sweet Springs Palace." },
  { zh: "二月，行幸盩厔五柞宮。", literal: "In the second month, he traveled in favor to Wuzuo Palace at Zhouzhi.", idiomatic: "In the second month he traveled to Wuzuo Palace at Zhouzhi." },
  { zh: "---- 2 上病篤，霍光涕泣問曰：「如有不諱，誰當嗣者？", literal: "----2 The emperor's illness was grave; Huo Guang, weeping, asked: \"If there should be no taboo, who ought to succeed?", idiomatic: "----2 The emperor's illness was grave; Huo Guang, weeping, asked, \"If the worst should come, who ought to succeed?" },
  { zh: "」上曰：「君未諭前畫意邪？", literal: "\" The emperor said: \"Have you not understood the meaning of the earlier painting?", idiomatic: "\" The emperor said, \"Have you not understood the meaning of the earlier painting?" },
  { zh: "立少子，君行周公之事。", literal: "Establish the younger son; you perform the affairs of the Duke of Zhou.", idiomatic: "Establish the younger son; you shall perform the Duke of Zhou's role." },
  { zh: "」光頓首讓曰：「臣不如金日磾！", literal: "\" Guang kowtowed and declined, saying: \"Your servant is not equal to Jin Midi!", idiomatic: "\" Guang kowtowed and declined, saying, \"Your servant is not equal to Jin Midi!" },
  { zh: "」日磾亦曰：「臣，外國人，不如光；", literal: "\" Midi also said: \"Your servant, a foreigner, is not equal to Guang;", idiomatic: "\" Midi also said, \"Your servant, a foreigner, is not equal to Guang;" },
  { zh: "且使匈奴輕漢矣！", literal: "moreover it would make the Xiongnu look down on Han!", idiomatic: "moreover it would make the Xiongnu look down on Han!" },
  { zh: "」乙丑，詔立弗陵為皇太子，時年八歲。", literal: "\" On yichou, an edict established Fuling as heir apparent; he was then eight years old.", idiomatic: "\" On yichou an edict established Fuling as heir apparent; he was then eight years old." },
  { zh: "丙寅，以光為大司馬、大將軍，日磾為車騎將軍，太僕上官桀為左將軍，受遺詔輔少主，又以搜粟都尉桑弘羊為御史大夫，皆拜臥內床下。", literal: "On bingyin, Guang was made Grand Marshal and Grand General, Midi Commandant of Cavalry, Grand Coachman Shangguan Jie Left General—all received the testamentary edict to assist the young ruler; Search-for-Grain Colonel Sang Hongyang was also made Censor-in-Chief; all were appointed below the bed in the sleeping chamber.", idiomatic: "On bingyin, Guang was made grand marshal and grand general, Midi commandant of cavalry, and Grand Coachman Shangguan Jie left general—all received the testamentary edict to assist the young ruler; Search-for-Grain Colonel Sang Hongyang was also made censor-in-chief; all were appointed below the bed in the sleeping chamber." },
  { zh: "光出入禁闥二十餘年，出則奉車，入侍左右，小心謹慎，未嘗有過。", literal: "Guang had entered and left the forbidden gates more than twenty years; going out he attended the carriage, entering he served at left and right—careful and cautious, never having fault.", idiomatic: "Guang had served within the forbidden gates for more than twenty years; going out he attended the carriage, entering he served at the emperor's side—careful and cautious, never at fault." },
  { zh: "為人沈靜詳審，每出入、下殿門，止進有常處，郎、僕射竊識視之，不失尺寸。", literal: "As a man he was deep, calm, detailed, and thorough; whenever he went out or in or descended the hall gate, his stopping and advancing had fixed places; gentlemen and masters of attendants secretly marked and observed him—not off by a fraction of an inch.", idiomatic: "He was deep, calm, and thorough; whenever he went out or in or descended the hall gate, his stopping and advancing had fixed places; gentlemen and masters of attendants secretly marked him—not off by an inch." },
  { zh: "日磾在上左右，目不忤視者數十年；", literal: "Midi was at the emperor's left and right; for decades his eyes never met the emperor's gaze improperly;", idiomatic: "Midi was at the emperor's side; for decades his eyes never met the emperor's gaze improperly;" },
  { zh: "賜出宮女，不敢近；", literal: "when palace women were granted and sent out, he did not dare approach;", idiomatic: "when palace women were granted and sent out, he did not dare approach;" },
  { zh: "上欲內其女後宮，不肯；", literal: "the emperor wished to take his daughter into the rear palace—he would not;", idiomatic: "the emperor wished to take his daughter into the inner palace—he refused;" },
  { zh: "其篤慎如此，上尤奇異之。", literal: "his earnest caution was like this; the emperor especially marveled at him.", idiomatic: "his earnest caution was such; the emperor especially marveled at him." },
  { zh: "日磾長子為帝弄兒，帝甚愛之，其後弄兒壯大，不謹，自殿下與宮人戲；", literal: "Midi's eldest son was the emperor's playboy; the emperor greatly loved him; afterward the playboy grew large, was not careful, and from below the hall played with palace women;", idiomatic: "Midi's eldest son was the emperor's playboy; the emperor greatly loved him; later the playboy grew up, was careless, and from below the hall played with palace women;" },
  { zh: "日磾適見之，惡其淫亂，遂殺弄兒。", literal: "Midi happened to see it, hated its licentious disorder, and thereupon killed the playboy.", idiomatic: "Midi happened to see it, hated the licentious conduct, and killed the playboy." },
  { zh: "上聞之，大怒，日磾頓首謝，具言所以殺弄兒狀。", literal: "The emperor heard it and was greatly angry; Midi kowtowed and apologized, fully stating the reason for killing the playboy.", idiomatic: "The emperor heard and was greatly angry; Midi kowtowed and apologized, fully explaining why he had killed the playboy." },
  { zh: "上甚哀，為之泣；", literal: "The emperor was deeply grieved and wept for him;", idiomatic: "The emperor was deeply grieved and wept for him;" },
  { zh: "已而心敬日磾。", literal: "shortly after, in his heart he respected Midi.", idiomatic: "shortly after he came to respect Midi in his heart." },
  { zh: "上官桀始以材力得幸，為未央廄令；", literal: "Shangguan Jie at first obtained favor through talent and strength and was made Weiyang Stable Director;", idiomatic: "Shangguan Jie at first won favor through talent and strength and was made Weiyang Stable Director;" },
  { zh: "上嘗體不安，及愈，見馬，馬多瘦，上大怒曰：「令以我不復見馬邪！", literal: "The emperor once was physically unwell; when he recovered and saw the horses, many horses were thin; the emperor was greatly angry and said: \"Director, do you think I will never see horses again!", idiomatic: "The emperor once was unwell; when he recovered and saw the horses, many were thin; the emperor was greatly angry and said, \"Director, do you think I will never see horses again!" },
  { zh: "」欲下吏。", literal: "\" He wished to send him down to the clerks.", idiomatic: "\" He wished to hand him over to the law officers." },
  { zh: "桀頓首曰：「臣聞聖體不安，日夜憂懼，意誠不在馬。", literal: "Jie kowtowed and said: \"Your servant heard the sage body was unwell and day and night was anxious and fearful—the intent truly was not on horses.", idiomatic: "Jie kowtowed and said, \"Your servant heard Your Majesty was unwell and day and night was anxious and fearful—my mind truly was not on the horses." },
  { zh: "」言未卒，泣數行下。", literal: "\" Before his words ended, tears flowed down several lines.", idiomatic: "\" Before he finished speaking, tears streamed down his face." },
  { zh: "上以為愛己，由是親近，為侍中，稍遷至太僕。", literal: "The emperor thought he loved himself; from this he drew near, made him attendant-in-ordinary, and gradually promoted him to Grand Coachman.", idiomatic: "The emperor thought he loved him; from this he drew him near, made him attendant-in-ordinary, and gradually promoted him to grand coachman." },
  { zh: "三人皆上素所愛信者，故特舉之，授以後事。", literal: "The three men were all those the emperor had long loved and trusted; therefore he especially raised them and entrusted them with later affairs.", idiomatic: "All three were men the emperor had long loved and trusted; therefore he especially raised them and entrusted them with affairs after his death." },
  { zh: "丁卯，帝崩於五柞宮；", literal: "On dingmao the emperor collapsed at Wuzuo Palace;", idiomatic: "On dingmao the emperor died at Wuzuo Palace;" },
  { zh: "入殯未央宮前殿。", literal: "he was brought in to lie in state at the front hall of Weiyang Palace.", idiomatic: "his body was brought to lie in state at the front hall of Weiyang Palace." },
  { zh: "帝聰明能斷，善用人，行法無所假貸。", literal: "The emperor was intelligent and able to decide, good at employing men, and in applying law gave no indulgence.", idiomatic: "The emperor was intelligent and decisive, good at employing men, and in applying the law gave no indulgence." },
  { zh: "隆慮公主子昭平君尚帝女夷安公主。", literal: "The son of Princess Longlü, Zhaoping Jun, married the emperor's daughter Princess Yian.", idiomatic: "Princess Longlü's son Zhaoping Jun married the emperor's daughter Princess Yian." },
  { zh: "隆慮主病困，以金千斤、錢千萬為昭平君豫贖死罪，上許之。", literal: "Princess Longlü, gravely ill, offered a thousand jin of gold and ten million cash for Zhaoping Jun to redeem capital crime in advance; the emperor assented.", idiomatic: "Princess Longlü, gravely ill, offered a thousand jin of gold and ten million cash for Zhaoping Jun to redeem capital crime in advance; the emperor assented." },
  { zh: "隆慮主卒，昭平君日驕，醉殺主傅，繫獄；", literal: "Princess Longlü died; Zhaoping Jun daily grew arrogant, drunkenly killed the princess's tutor, and was imprisoned;", idiomatic: "Princess Longlü died; Zhaoping Jun daily grew arrogant, drunkenly killed the princess's tutor, and was imprisoned;" },
  { zh: "廷尉以公主子上請。", literal: "the Commandant of Justice memorialized upward as the princess's son.", idiomatic: "the commandant of justice memorialized upward as the princess's son." },
  { zh: "左右人人為言：「前又入贖，陛下許之。", literal: "Those left and right each spoke for him: \"Formerly he also paid ransom; Your Majesty assented.", idiomatic: "Those at his side all spoke for him: \"Formerly he also paid ransom; Your Majesty assented." },
  { zh: "」上曰：「吾弟老有是一子，死，以屬我。", literal: "\" The emperor said: \"My sister in old age had this one son; when she died, she entrusted him to me.", idiomatic: "\" The emperor said, \"My sister in her old age had this one son; when she died she entrusted him to me." },
  { zh: "」於是為之垂涕，歎息良久，曰：「法令者，先帝所造也，用弟故而誣先帝之法，吾何面目入高廟乎！", literal: "\" Thereupon he shed tears for him, sighed long, and said: \"Laws and ordinances are what the Former Emperor made; using my sister's reason to deceive the Former Emperor's law—what face have I to enter the High Temple!", idiomatic: "\" Thereupon he shed tears for him, sighed long, and said, \"Laws and ordinances are what the Former Emperor made; using my sister's sake to betray the Former Emperor's law—what face have I to enter the High Temple!" },
  { zh: "又下負萬民。", literal: "Moreover below I would wrong the myriad people.", idiomatic: "Moreover below I would wrong the myriad people." },
  { zh: "」乃可其奏，哀不能自止，左右盡悲，待詔東方朔前上壽，曰：「臣聞聖王為政，賞不避仇讎，誅不擇骨肉。", literal: "\" He thereupon approved the memorial; grief could not stop itself; those left and right were all sorrowful. Awaiting-edict Dongfang Shuo came forward to offer longevity, saying: \"Your servant has heard that sage kings in governing reward without avoiding enemies and execute without choosing kin.", idiomatic: "\" He thereupon approved the memorial; his grief could not stop; those at his side were all sorrowful. Awaiting-edict Dongfang Shuo came forward to offer congratulations, saying, \"Your servant has heard that sage kings in governing reward without avoiding enemies and execute without choosing kin." },
  { zh: "《書》曰：『不偏不黨，王道蕩蕩。", literal: "The Documents says: 'Without partiality, without faction—the kingly way is vast and open.", idiomatic: "The Documents says, 'Without partiality, without faction—the kingly way is vast and open." },
  { zh: "』此二者，五帝所重，三王所難也，陛下行之，天下幸甚！", literal: "' These two points the Five Emperors valued and the Three Kings found difficult; Your Majesty practices them—all under Heaven is most fortunate!", idiomatic: "' These two points the Five Emperors valued and the Three Kings found difficult; Your Majesty practices them—all under Heaven is most fortunate!" },
  { zh: "臣朔奉觴昧死再拜上萬歲壽！", literal: "Your servant Shuo, offering the cup, risking death, twice kowtows and offers ten-thousand-year longevity!", idiomatic: "Your servant Shuo, offering the cup, risking death, twice kowtows and offers ten-thousand-year longevity!" },
  { zh: "」上初怒朔，既而善之，以朔為中郎。", literal: "\" At first the emperor was angry at Shuo; shortly after he approved of him and made Shuo a palace gentleman.", idiomatic: "\" At first the emperor was angry at Shuo; shortly after he approved of him and made Shuo a palace gentleman." },
  { zh: ":班固贊曰：漢承百王之弊，高祖撥亂反正，文、景務在養民，至於稽古禮文之事，猶多闕焉。", literal: ": Ban Gu's praise says: Han inherited the defects of a hundred kings; Gaozu swept away disorder and returned to correctness; Wen and Jing strove to nourish the people—as for examining antiquity in ritual and literary matters, many still were lacking.", idiomatic: ": Ban Gu's praise says: Han inherited the defects of a hundred kings; Gaozu swept away disorder and restored order; Wen and Jing strove to nourish the people—as for examining antiquity in ritual and literary matters, many still were lacking." },
  { zh: "孝武初立，卓然罷黜百家，表章《六經》，遂疇咨海內，舉其俊茂，與之立功；", literal: "When Emperor Xiao Wu first took the throne, he outstandingly dismissed the Hundred Schools and displayed and honored the Six Classics; he thereupon consulted within the seas, raised their outstanding and lush talent, and with them established achievement;", idiomatic: "When Emperor Wu first took the throne, he outstandingly dismissed the Hundred Schools and displayed the Six Classics; he thereupon consulted within the realm, raised outstanding talent, and with them established achievements;" },
  { zh: "興太學，修郊祀，改正朔，定歷數，協音律，作詩樂，建封禪，禮百神，紹周後，號令文章，煥焉可述，後嗣得遵洪業而有三代之風。", literal: "he raised the Imperial Academy, repaired suburban sacrifices, corrected the calendar beginning, fixed calendrical reckoning, harmonized pitch pipes, composed poetry and music, established feng and chan, honored the hundred spirits, continued Zhou's succession, and orders and writings blazed forth and could be narrated—later successors could follow the great enterprise and have the manner of the Three Dynasties.", idiomatic: "he raised the Imperial Academy, repaired suburban sacrifices, corrected the calendar, fixed calendrical reckoning, harmonized pitch pipes, composed poetry and music, established feng and chan, honored the hundred spirits, continued Zhou's succession, and his orders and writings blazed forth and could be narrated—later successors could follow the great enterprise and have the manner of the Three Dynasties." },
  { zh: "如武帝之雄材大略，不改文、景之恭儉以濟斯民，雖《詩》、《書》所稱何有加焉！", literal: "If one like Emperor Wu's heroic talent and great design had not altered Wen and Jing's respectful frugality to aid these people—even what the Odes and Documents praise, what could be added!", idiomatic: "If one of Emperor Wu's heroic talent and great design had not altered Wen and Jing's respectful frugality to aid the people—even what the Odes and Documents praise, what could be added!" },
  { zh: ":臣光曰：孝武窮奢極欲，繁刑重斂，內侈宮室，外事四夷，信惑神怪，巡遊無度，使百姓疲敝，起為盜賊，其所以異於秦始皇者無幾矣。", literal: ": Minister Guang said: Emperor Xiao Wu exhausted luxury and extreme desire, multiplied punishments and heavy levies, inwardly was extravagant in palaces, outwardly served the four Yi, believed and was deluded by spirits and marvels, toured without measure, made the hundred people weary and exhausted until they rose as bandits—the ways he differed from Qin Shihuang were few.", idiomatic: ": Minister Guang said: Emperor Wu exhausted luxury and extreme desire, multiplied punishments and heavy levies, was extravagant in palaces within, served the four barbarians without, believed spirits and marvels, toured without measure, wore out the people until they rose as bandits—the ways he differed from Qin Shihuang were few." },
  { zh: "然秦以之亡，漢以之興者，孝武能尊先王之道，知所統守，受忠直之言，惡人欺蔽，好賢不倦，誅賞嚴明，晚而改過，顧托得人，此其所以有亡秦之失而免亡秦之禍乎！", literal: "Yet Qin through this perished and Han through this rose because Emperor Xiao Wu was able to honor the Former Kings' Way, know what to uphold and guard, accept loyal and straight words, hate men who deceived and covered, love the worthy without weariness, punish and reward with strict clarity, late in life reform faults, and in entrusting care obtain the right men—this is why he had Qin's faults yet escaped Qin's calamity!", idiomatic: "Yet Qin through this perished and Han through this rose because Emperor Wu was able to honor the way of the former kings, know what to uphold, accept loyal and straight counsel, hate deception, love the worthy without weariness, punish and reward with strict clarity, reform late in life, and in entrusting care obtain the right men—this is why he had Qin's faults yet escaped Qin's calamity!" },
  { zh: "---- 3 戊辰，太子即皇帝位。", literal: "----3 On wuchen the heir apparent took the emperor's throne.", idiomatic: "----3 On wuchen the heir apparent took the throne." },
  { zh: "帝姊鄂邑公主共養省中，霍光、金日磾、上官桀共領尚書事。", literal: "The emperor's elder sister the Princess of Eyi jointly nourished him within the inner palace; Huo Guang, Jin Midi, and Shangguan Jie jointly headed Secretariat affairs.", idiomatic: "The emperor's elder sister the Princess of Eyi jointly raised him within the inner palace; Huo Guang, Jin Midi, and Shangguan Jie jointly headed Secretariat affairs." },
  { zh: "光輔幼主，政自己出，天下想聞其風采。", literal: "Guang assisted the young ruler; government issued from himself; all under Heaven longed to hear his manner and bearing.", idiomatic: "Guang assisted the young ruler; government issued from himself; all under Heaven longed to hear his manner and bearing." },
  { zh: "殿中嘗有怪，一夜，群臣相驚，光召尚符璽郎，欲收取璽。", literal: "Once there was a marvel in the hall; one night the host of ministers were startled together; Guang summoned the gentleman of the Office of Tallies and Seals and wished to take and secure the seal.", idiomatic: "Once there was a marvel in the hall; one night the ministers were startled together; Guang summoned the gentleman of the Office of Tallies and Seals and wished to take and secure the seal." },
  { zh: "郎不肯授，光欲奪之。", literal: "The gentleman would not hand it over; Guang wished to seize it.", idiomatic: "The gentleman would not hand it over; Guang wished to seize it." },
  { zh: "郎按劍曰：「臣頭可得，璽不可得也！", literal: "The gentleman grasped his sword and said: \"Your servant's head can be obtained—the seal cannot be obtained!", idiomatic: "The gentleman grasped his sword and said, \"Your servant's head can be taken—the seal cannot be taken!" },
  { zh: "」光甚誼之。", literal: "\" Guang greatly approved of him.", idiomatic: "\" Guang greatly approved of him." },
  { zh: "明日，詔增此郎秩二等。", literal: "The next day, an edict increased this gentleman's rank by two grades.", idiomatic: "The next day an edict increased this gentleman's rank by two grades." },
  { zh: "眾庶莫不多光。", literal: "The common multitude none did not admire Guang.", idiomatic: "The common people all admired Guang." },
  { zh: "---- 4 三月，甲辰，葬孝武皇帝於茂陵。", literal: "----4 In the third month, on jiachen, Emperor Xiao Wu was buried at Maoling.", idiomatic: "----4 In the third month, on jiachen, Emperor Wu was buried at Maoling." },
  { zh: "---- 5 夏，六月，赦天下。", literal: "----5 In summer, the sixth month, an amnesty for all under Heaven.", idiomatic: "----5 In summer, the sixth month, there was an amnesty for all under Heaven." },
  { zh: "---- 6 秋，七月，有星孛於東方。", literal: "----6 In autumn, the seventh month, a broom star appeared in the east.", idiomatic: "----6 In autumn, the seventh month, a comet appeared in the east." },
  { zh: "---- 7 濟北王寬坐禽獸行自殺。", literal: "----7 The King of Jibei, Kuan, convicted of beastly conduct, committed suicide.", idiomatic: "----7 The King of Jibei, Kuan, convicted of beastly conduct, committed suicide." },
  { zh: "---- 8 冬，匈奴入朔方，殺略吏民；", literal: "----8 In winter, the Xiongnu entered Shuofang, killed and plundered officials and people;", idiomatic: "----8 In winter the Xiongnu entered Shuofang, killed and plundered officials and people;" },
  { zh: "發軍屯西河，左將軍桀行北邊。", literal: "troops were dispatched to garrison Xihe; Left General Jie marched the northern border.", idiomatic: "troops were dispatched to garrison Xihe; Left General Jie marched the northern border." },
  { zh: "---- category:資治通鑑", literal: "---- category: Zizhi Tongjian", idiomatic: "---- category: Zizhi Tongjian" }
];
